/* Generated by gen_packs.py from the original data files: pack "next_evol". */
MC.registerPack({"id":"next_evol","cards":[{"id":"40001a","name":"케이블","en":"* Cable","type":"hero","enc":false,"unique":true,"hp":12,"atk":2,"thw":2,"def":2,"hs":5,"tr":["SOLDIER","X-FORCE"],"traits":["군인","엑스포스"],"text":"<b>반응</b>: 케이블이 부가 음모 하나를 격파한 후, 그를 준비합니다. (페이즈마다 1회 제한.)"},{"id":"40001b","name":"네이선 서머스","en":"* Nathan Summers","type":"alter","enc":false,"unique":true,"hp":12,"rec":4,"hs":6,"tr":["MUTANT","SOLDIER"],"traits":["뮤턴트","군인"],"text":"당신은 어떤 성향의 플레이어 부가 음모든 당신의 덱에 포함할 수 있습니다.\n솔져 X — <b>사전 준비</b>: 당신의 덱과 버린 더미에서 플레이어 부가 음모 하나를 찾아 플레이 영역에 내려놓습니다. <i>(덱을 섞습니다.)</i>"},{"id":"40002","name":"바디슬라이드","en":"Bodyslide","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Hero","tr":[],"traits":[],"text":"<b>행동</b>: 형태를 변신합니다. 다른 각 플레이어는 당신과 같은 형태로 변신해도 됩니다."},{"id":"40003","name":"정신 스캔","en":"Mind Scan","type":"event","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["PSIONIC","SUPERPOWER","THWART"],"traits":["사이오닉","슈퍼파워","저지"],"text":"<b>히어로 행동</b> <i>(저지)</i>: 음모 하나에서 위협을 3만큼 제거합니다. 승점 구역에 있는 부가 음모마다 그 음모에서 위협을 1만큼 추가로 제거합니다."},{"id":"40004","name":"예지","en":"Precognition","type":"event","enc":false,"unique":false,"cost":0,"res":"B","cls":"Hero","tr":["PSIONIC","SUPERPOWER"],"traits":["사이오닉","슈퍼파워"],"text":"<b>히어로 행동</b>: 조우 덱 맨 위에서 카드 X장을 봅니다. X는 승점 구역에 있는 부가 음모의 수입니다. 그 카드 중 1장을 버려도 됩니다. 나머지는 원하는 순서대로 되돌려 놓습니다."},{"id":"40005","name":"염동력 폭발","en":"Telekinetic Blast","type":"event","enc":false,"unique":false,"cost":3,"res":"Y","cls":"Hero","tr":["ATTACK","PSIONIC","SUPERPOWER"],"traits":["공격","사이오닉","슈퍼파워"],"text":"<b>히어로 행동</b> <i>(공격)</i>: 적 하나에게 피해 6점을 입힙니다. 승점 구역에 있는 부가 음모마다 그 적에게 피해 1점을 추가로 입힙니다."},{"id":"40006","name":"테크노바이러스 정화","en":"* Technovirus Purge","type":"pside","enc":false,"unique":true,"cost":0,"start":5,"res":"Y","cls":"Hero","tr":[],"victory":0,"traits":[],"text":"승점 0.\n케이블 이외의 캐릭터는 테크노바이러스 정화에서 위협을 제거할 수 없습니다.\n테크노바이러스 정화가 승점 구역에 있는 동안, 네이선 서머스와 케이블은 [[사이오닉]] 특성을 얻고 케이블은 저지 +1, 공격 +1, 방어 +1을 받습니다."},{"id":"40007","name":"그레이말킨","en":"* Graymalkin","type":"support","enc":false,"unique":true,"cost":2,"res":"Y","cls":"Hero","tr":["LOCATION"],"traits":["장소"],"text":"<b>반응</b>: 부가 음모 하나가 격파된 후, 그레이말킨을 준비합니다.\n<b>자원</b>: 그레이말킨을 소진 → [energy] 자원 1개를 생성."},{"id":"40008","name":"프로페서","en":"* Professor","type":"support","enc":false,"unique":true,"cost":1,"res":"B","cls":"Hero","tr":["PERSONA","TECH"],"traits":["페르소나","과학"],"text":"<b>일상 행동</b>: 프로페서를 소진 → 카드 1장을 뽑거나, 당신의 덱과 버린 더미에서 플레이어 부가 음모 하나를 찾아 당신의 손에 더하는 것 중 하나를 선택. <i>(덱을 섞습니다.)</i>"},{"id":"40009","name":"아스카니손","en":"* Askani'son","type":"upgrade","enc":false,"unique":true,"cost":1,"res":"G","cls":"Hero","tr":["TITLE"],"traits":["칭호"],"text":"<b>히어로 반응</b> <i>(저지)</i>: 당신이 적의 공격을 방어한 후, 아스카니손을 소진하고 [energy] 자원을 소모 → 당신의 히어로의 저지 수치만큼 음모 하나에서 위협을 제거."},{"id":"40010","name":"강제 기억 상실","en":"Forced Amnesia","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"B","cls":"Hero","tr":["PSIONIC","SUPERPOWER"],"traits":["사이오닉","슈퍼파워"],"text":"<b>히어로 반응</b>: <i>(영속이 아닌)</i> 부가 음모 하나가 격파된 후, 강제 기억 상실과 그 부가 음모를 승점 구역에 더합니다."},{"id":"40011","name":"플라스마 라이플","en":"Plasma Rifle","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"R","cls":"Hero","tr":["TECH","WEAPON"],"restricted":1,"traits":["과학","무기"],"text":"한정.\n<b>히어로 행동</b> <i>(공격)</i>: 플라스마 라이플을 소진하고 [energy] 자원을 소모 → 승점 구역에 있는 부가 음모마다 적 하나에게 피해 1점을 입힘(최대 4점). 이 공격은 원거리를 얻음."},{"id":"40012","name":"염동력 역장","en":"Telekinetic Force Field","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"R","cls":"Hero","tr":["PSIONIC","SUPERPOWER"],"traits":["사이오닉","슈퍼파워"],"text":"히어로 형태 전용\n<b>히어로 난입</b>: 아군 캐릭터가 피해를 입으려 할 때, 염동력 역장을 버림 → 그 피해를 모두 방지."},{"id":"40013","name":"시간 도약","en":"Temporal Leap","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"R","cls":"Hero","tr":["TACTIC"],"traits":["전술"],"text":"<b>히어로 난입</b>: 주요 음모가 완료되려 할 때, 이 카드를 게임에서 제거하고 승점 구역에 있는 부가 음모 하나를 플레이 영역에 내려놓음 → 주요 음모에서 그 부가 음모로 위협을 4만큼 옮김."},{"id":"40014","name":"칼리반","en":"* Caliban","type":"ally","enc":false,"unique":true,"hp":3,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"B","cls":"Leadership","tr":["PSIONIC","X-FORCE"],"traits":["사이오닉","엑스포스"],"text":"<b>반응</b>: 칼리반이 플레이 영역에 들어온 후, [[엑스팩터]], [[엑스포스]], 또는 [[엑스맨]] 동료가 버려질 때까지 당신의 덱 맨 위에서 카드를 버립니다. 그 동료를 당신의 손에 더합니다."},{"id":"40015","name":"팬토멕스","en":"* Fantomex","type":"ally","enc":false,"sub":"찰리 클러스터-7","unique":true,"hp":3,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":4,"res":"Y","cls":"Leadership","tr":["PSIONIC","X-FORCE"],"traits":["사이오닉","엑스포스"],"text":"<b>반응</b>: 팬토멕스가 플레이 영역에 들어온 후, 당신의 덱과 버린 더미에서 E.V.A.를 찾아 플레이 영역에 내려놓습니다. <i>(덱을 섞습니다.)</i>"},{"id":"40016","name":"선스팟","en":"* Sunspot","type":"ally","enc":false,"sub":"바비 다 코스타","unique":true,"hp":2,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"Y","cls":"Leadership","tr":["AERIAL","X-FORCE"],"traits":["공중","엑스포스"],"text":"<b>반응</b>: 당신의 손에서 선스팟을 플레이한 후, 플레이어 하나를 선택 → 선스팟의 비용을 지불하는 데 사용된 [energy] 자원마다 빌런과 선택한 플레이어와 교전 중인 각 하수인에게 피해 1점을 입힘."},{"id":"40017","name":"작전 계획","en":"Mission Planning","type":"event","enc":false,"unique":false,"cost":2,"res":"B","cls":"Leadership","tr":[],"traits":[],"text":"승점 구역에 부가 음모가 있을 때만 플레이할 수 있습니다.\n<b>히어로 행동</b>: 이번 페이즈의 끝까지, 당신이 조종하는 동료는 부수적 피해를 입지 않습니다."},{"id":"40018","name":"증원 요청","en":"* Call for Backup","type":"pside","enc":false,"unique":true,"cost":1,"start":3,"startStar":true,"res":"B","cls":"Leadership","tr":[],"victory":0,"traits":[],"text":"승점 0.\n<b>격파될 때</b>: 각 플레이어는 자신의 덱과 버린 더미에서 동료 하나를 찾아 플레이 영역에 내려놓아도 됩니다. <i>(덱을 섞습니다.)</i>"},{"id":"40019","name":"장전 완료","en":"* Lock and Load","type":"pside","enc":false,"unique":true,"cost":1,"start":2,"startStar":true,"res":"R","cls":"Aggression","tr":[],"victory":0,"traits":[],"text":"승점 0.\n<b>격파될 때</b>: 각 플레이어는 자신의 덱과 버린 더미에서 자원 비용이 3 이하인 [[무기]] 업그레이드 하나를 찾아 플레이 영역에 내려놓아도 됩니다. <i>(덱을 섞습니다.)</i>"},{"id":"40020","name":"경계선 구축","en":"* Establish Perimeter","type":"pside","enc":false,"unique":true,"cost":1,"start":2,"startStar":true,"res":"Y","cls":"Protection","tr":[],"victory":0,"traits":[],"text":"승점 0.\n<b>격파될 때</b>: 각 아이덴티티에게 강인함 상태 카드를 줍니다."},{"id":"40021","name":"E.V.A.","en":"* E.V.A.","type":"support","enc":false,"unique":true,"cost":0,"res":"G","cls":"Leadership","tr":["VEHICLE"],"traits":["탈것"],"text":"팬토멕스가 플레이 영역에 없다면, E.V.A.를 버립니다.\n<b>행동</b>: E.V.A.를 소진 → 다음 중 하나를 선택:\n• 음모 하나에서 위협을 1만큼 제거.\n• 적 하나에게 피해 1점을 입힘.\n• 팬토멕스가 입은 피해 1점을 치료."},{"id":"40022","name":"언캐니 엑스포스","en":"Uncanny X-Force","type":"support","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Leadership","tr":["TEAM"],"maxPer":1,"traits":["팀"],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다. 플레이어마다 [[팀]] 카드 최대 1장.\n당신의 모든 캐릭터에게 [[엑스포스]] 특성이 있다면, 당신이 조종하는 각 동료는 저지 +1을 받고 부가 음모를 저지한 후 부수적 피해([cost])를 1점 덜 입습니다."},{"id":"40023","name":"임무 지휘관","en":"* Mission Leader","type":"upgrade","enc":false,"unique":true,"cost":2,"res":"R","cls":"Leadership","tr":["TITLE"],"traits":["칭호"],"text":"당신의 아이덴티티에게 [[군인]] 특성이 있다면, 임무 지휘관을 플레이하는 자원 비용이 1 감소합니다.\n<b>히어로 반응</b>: 부가 음모 하나가 격파된 후, 임무 지휘관을 소진 → 각 플레이어는 카드 1장을 뽑음."},{"id":"40024","name":"데드풀","en":"* Deadpool","type":"ally","enc":false,"sub":"웨이드 윌슨","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":3,"res":"G","cls":"Basic","tr":["MERCENARY","X-FORCE"],"traits":["용병","엑스포스"],"text":"<b>강제 난입</b>: 데드풀이 부수적 피해로 격파되려 할 때, 대신 그가 입은 피해 3점을 치료합니다. 주요 음모에 가속 토큰 1개를 추가합니다."},{"id":"40025","name":"데스록","en":"* Deathlok","type":"ally","enc":false,"sub":"유닛 L17","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":4,"res":"R","cls":"Basic","tr":["CYBORG","X-FORCE"],"traits":["사이보그","엑스포스"],"text":"<b>히어로 반응</b>: 데스록이 플레이 영역에 들어온 후, 아무 플레이어의 버린 더미에서 데스록에게 장착할 수 있는 자원 비용 1 이하의 업그레이드 하나를 선택합니다. 그 업그레이드를 데스록에게 장착합니다."},{"id":"40026","name":"애증 관계","en":"Frenemies","type":"event","enc":false,"unique":false,"cost":1,"res":"G","cls":"Basic","tr":["THWART"],"teamUp":["Cable","Deadpool"],"maxDeck":1,"traits":["저지"],"text":"협력(케이블 그리고 데드풀). 덱마다 최대 1장.\n<b>히어로 행동</b> <i>(저지)</i>: 케이블과 데드풀에게 각각 피해 1점을 입힙니다. 음모 하나에서 위협을 3만큼 제거하고, 다른 음모 하나에서 위협을 3만큼 제거합니다."},{"id":"40027","name":"지지 확보","en":"* Build Support","type":"pside","enc":false,"unique":true,"cost":1,"start":3,"startStar":true,"res":"B","cls":"Basic","tr":[],"victory":0,"traits":[],"text":"승점 0.\n<b>격파될 때</b>: 각 플레이어는 자신의 덱과 버린 더미에서 자원 비용이 3 이하인 지원 하나를 찾아 플레이 영역에 내려놓아도 됩니다. <i>(덱을 섞습니다.)</i>"},{"id":"40028","name":"정신의 힘","en":"The Power of the Mind","type":"resource","enc":false,"unique":false,"res":"B","cls":"Basic","tr":[],"traits":[],"text":"[[사이오닉]] 카드의 비용을 지불하는 동안, 이 카드가 생성하는 자원의 수가 두 배가 됩니다."},{"id":"40029","name":"사이미터","en":"* Psimitar","type":"upgrade","enc":false,"unique":true,"cost":2,"res":"Y","cls":"Basic","tr":["PSIONIC","WEAPON"],"restricted":1,"traits":["사이오닉","무기"],"text":"한정.\n<b>히어로 반응</b> <i>(공격)</i>: 당신이 다른 [[사이오닉]] 카드를 플레이한 후, 사이미터를 소진 → 적 하나에게 피해 2점을 입힘."},{"id":"40030","name":"보조 화기","en":"Sidearm","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"R","cls":"Basic","tr":["WEAPON"],"maxPer":1,"traits":["무기"],"text":"동료에게 장착합니다. 동료마다 1장 제한.\n장착된 동료는 공격 +1을 받고 그 동료의 공격은 원거리를 얻습니다.","link":"23035"},{"id":"40031","name":"테크노바이러스 재발","en":"Technovirus Resurgence","type":"obligation","enc":true,"set":"Cable","unique":false,"boost":2,"accel":1,"tr":[],"traits":[],"text":"<b><i>네이선 서머스 플레이어에게 이 카드를 줍니다.</i></b>\n<b>공개될 때</b>: 당신의 덱, 버린 더미, 손, 승점 구역에서 테크노바이러스 정화를 찾아 플레이 영역에 내려놓습니다. <i>(덱을 섞습니다.)</i> 이 카드를 테크노바이러스 정화에 장착합니다. 그럴 수 없다면, 이 카드를 버리고 당신에게 조우 카드 1장을 뒷면으로 나누어 줍니다."},{"id":"40032","name":"스트라이프","en":"* Stryfe","type":"minion","enc":true,"set":"Cable Nemesis","unique":true,"hp":5,"atk":2,"sch":2,"boost":3,"tr":["MUTANT LIBERATION FRONT","PSIONIC"],"villainous":1,"nemesis":true,"traits":["뮤턴트 해방 전선","사이오닉"],"text":"악당.\n<b>강제 난입</b>: 플레이어가 [[사이오닉]] 이벤트를 플레이할 때, 그 이벤트의 효과를 무효화하고 스트라이프에게 피해 1점을 입힙니다."},{"id":"40033","name":"백 투 더 퓨처","en":"Back to the Future","type":"side","enc":true,"set":"Cable Nemesis","unique":false,"boost":2,"start":4,"tr":[],"traits":[],"text":"케이블 플레이어는 백 투 더 퓨처 이외의 음모에서 위협을 제거할 수 없습니다. 다른 플레이어는 백 투 더 퓨처에서 위협을 제거할 수 없습니다.\n케이블 플레이어는 자신과 교전 중이지 않은 적에게 피해를 입힐 수 없습니다. 다른 플레이어는 케이블 플레이어와 교전 중인 하수인에게 피해를 입힐 수 없습니다."},{"id":"40034","name":"염동력 역장","en":"Telekinetic Force Field","type":"attachment","enc":true,"set":"Cable Nemesis","unique":false,"boost":1,"tr":["PSIONIC"],"traits":["사이오닉"],"text":"스트라이프에게 장착합니다. 그럴 수 없다면, 빌런에게 장착합니다.\n<b>강제 난입</b>: 장착된 캐릭터가 피해를 입으려 할 때, 그 피해를 방지합니다. 이렇게 피해가 2점 이상 방지되었다면, 이 카드를 버립니다.\n<hr />\n[star] <b>강화</b>: 이 카드를 활성화 중인 적에게 장착합니다.","star":true,"boostStar":true},{"id":"40035","name":"정신 스캔","en":"Mind Scan","type":"treachery","enc":true,"set":"Cable Nemesis","unique":false,"tr":["PSIONIC"],"traits":["사이오닉"],"text":"<b>공개될 때</b>: 주요 음모에 위협을 2만큼 놓습니다. 승점 구역에 있는 부가 음모마다 주요 음모에 위협을 1만큼 추가로 놓습니다.\n<hr />\n[star] <b>강화</b>: 당신은 혼란에 빠집니다.","star":true,"boostStar":true},{"id":"40036","name":"염동력 폭발","en":"Telekinetic Blast","type":"treachery","enc":true,"set":"Cable Nemesis","unique":false,"tr":["PSIONIC"],"traits":["사이오닉"],"text":"<b>공개될 때</b>: 피해 2점을 입습니다. 승점 구역에 있는 부가 음모마다 피해 1점을 추가로 입습니다.\n<hr />\n[star] <b>강화</b>: 당신은 기절합니다.","star":true,"boostStar":true},{"id":"40037a","name":"도미노","en":"* Domino","type":"hero","enc":false,"unique":true,"hp":9,"atk":2,"thw":1,"def":3,"hs":5,"tr":["POSSE","X-FORCE"],"traits":["패거리","엑스포스"],"text":"덱 맨 위에서 버려진 카드의 자원을 셀 때, 인쇄된 각 [wild] 아이콘을 두 번 셉니다.\n<b>행동</b>: 당신의 손에 있는 카드 1장을 선택합니다. 그 카드를 당신의 덱 맨 위 카드와 맞바꿉니다. (라운드마다 1회 제한.)"},{"id":"40037b","name":"니나 서먼","en":"* Neena Thurman","type":"alter","enc":false,"unique":true,"hp":9,"rec":3,"hs":6,"tr":["MUTANT"],"traits":["뮤턴트"],"text":"<b>행동</b>: 당신의 손에 있는 카드 1장을 선택합니다. 그 카드를 당신의 버린 더미 맨 위 카드와 맞바꿉니다. (라운드마다 1회 제한.)"},{"id":"40038","name":"다이아몬드백","en":"* Diamondback","type":"ally","enc":false,"sub":"레이첼 레이턴","unique":true,"hp":2,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":2,"res":"G","cls":"Hero","tr":["POSSE"],"traits":["패거리"],"text":"<b>행동</b>: 다이아몬드백을 소진하고, 그녀에게 피해 1점을 입히고, 당신의 덱 맨 위 카드를 버림 → 이렇게 버려진 자원 아이콘마다 각 적에게 피해 1점을 입힘."},{"id":"40039","name":"아웃로","en":"* Outlaw","type":"ally","enc":false,"sub":"이네즈 템플","unique":true,"hp":3,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"G","cls":"Hero","tr":["OUTLAW","POSSE"],"toughness":1,"traits":["무법자","패거리"],"text":"강인.\n[star] <b>난입</b>: 아웃로가 공격할 때, 당신의 덱 맨 위 카드를 버림 → 이렇게 버려진 자원 아이콘마다 아웃로는 이 공격에서 공격 +1을 받음.","star":true},{"id":"40040","name":"좋은 운동","en":"A Good Workout","type":"event","enc":false,"unique":false,"cost":2,"res":"G","cls":"Hero","tr":["ATTACK","SUPERPOWER"],"traits":["공격","슈퍼파워"],"text":"<b>히어로 행동</b> <i>(공격)</i>: 적 하나에게 피해 4점을 입히고 당신의 덱 맨 위 카드를 버립니다. 이렇게 버려진 자원 아이콘마다, 적 하나에게 피해 1점을 추가로 입힙니다."},{"id":"40041","name":"행운의 여신이여","en":"Luck Be a Lady","type":"event","enc":false,"unique":false,"cost":1,"res":"G","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"<b>히어로 행동</b>: 당신의 덱 맨 위 카드를 버리고 그 카드의 자원을 셉니다. 이렇게 센 자원마다, 그 자원이 다음과 같다면:\n[energy] - 캐릭터 하나가 입은 피해 2점을 치료합니다.\n[mental] - 음모 하나에서 위협을 2만큼 제거합니다.\n[physical] - 적 하나에게 피해 3점을 입힙니다.\n[wild] - 위의 것 중 하나를 선택합니다."},{"id":"40042","name":"적시적소","en":"Right Place, Right Time","type":"event","enc":false,"unique":false,"cost":2,"res":"G","cls":"Hero","tr":["SUPERPOWER","THWART"],"traits":["슈퍼파워","저지"],"text":"<b>히어로 행동</b> <i>(저지)</i>: 음모 하나에서 위협을 3만큼 제거하고 당신의 덱 맨 위 카드를 버립니다. 이렇게 버려진 자원 아이콘마다, 그 음모에서 위협을 1만큼 추가로 제거합니다."},{"id":"40043","name":"대박!","en":"Jackpot!","type":"resource","enc":false,"unique":false,"res":"RYB","cls":"Hero","tr":[],"traits":[],"text":"<b>반응</b>: 이 카드가 당신의 덱 맨 위에서 버려진 후, 이 카드를 당신의 덱에 다시 섞어 넣습니다."},{"id":"40044","name":"퍼그 핍","en":"* Pip the Pug","type":"support","enc":false,"unique":true,"cost":1,"res":"G","cls":"Hero","tr":["CREATURE"],"traits":["괴수"],"text":"<b>일상 행동</b>: 퍼그 핍을 소진 → 당신의 버린 더미에서 도미노 카드 또는 [[패거리]] 카드 1장을 당신의 덱 맨 위에 놓음."},{"id":"40045","name":"페인티드 레이디호","en":"* The Painted Lady","type":"support","enc":false,"unique":true,"cost":1,"res":"G","cls":"Hero","tr":["VEHICLE"],"traits":["탈것"],"text":"<b>반응</b>: 당신이 덱 맨 위에서 카드를 버린 후, 그 카드를 이 카드에 뒷면으로 장착합니다(최대 3장).\n<b>일상 행동</b>: 페인티드 레이디호를 소진 → 이 카드에 장착된 카드 1장을 당신의 손에 더함."},{"id":"40046","name":"도미노의 권총","en":"Domino's Pistol","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"G","cls":"Hero","tr":["WEAPON"],"restricted":1,"traits":["무기"],"text":"한정.\n<b>히어로 행동</b> <i>(공격)</i>: 도미노의 권총을 소진하고, 적 하나를 선택하고, 당신의 덱 맨 위 카드를 버림 → 이렇게 버려진 자원 아이콘마다 그 적에게 피해 1점을 입힘. 이 공격은 원거리를 얻음."},{"id":"40047","name":"운도 실력","en":"Lucky and Good","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"G","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"<b>히어로 난입</b> <i>(방어)</i>: 당신을 상대로 한 공격 중에 강화 카드가 앞면으로 뒤집힐 때, 운도 실력을 소진 → 그 카드의 강화 아이콘과 \"<b>강화</b>\" 능력을 무효화. 이 공격에서 공격 중인 적에게 강화 카드 1장을 더 줌."},{"id":"40048","name":"뜻밖의 행운","en":"Lucky Break","type":"upgrade","enc":false,"unique":false,"cost":0,"res":"G","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"<b>히어로 난입</b>: 당신이 조우 카드를 공개할 때, 뜻밖의 행운을 버림 → 그 카드의 효과를 무효화하고 그 카드를 버림. 조우 덱에서 다른 카드 1장을 공개."},{"id":"40049","name":"확률장","en":"Probability Field","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"G","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"<b>난입</b>: 당신이 기본 기능을 사용할 때, 당신의 덱 맨 위 카드를 버림 → 이렇게 버려진 자원 아이콘마다 이번 사용에서 당신은 그 기능에 +1을 받음."},{"id":"40050","name":"페럴","en":"* Feral","type":"ally","enc":false,"sub":"마리아 칼라산토스","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":4,"res":"Y","cls":"Justice","tr":["X-FORCE"],"traits":["엑스포스"],"text":"[star] <b>반응</b>: 페럴이 저지한 후, 당신의 덱 맨 위 카드를 버립니다. 이렇게 버려진 자원 아이콘마다, 빌런에게 피해 1점을 입힙니다.","star":true},{"id":"40051","name":"울프스베인","en":"* Wolfsbane","type":"ally","enc":false,"sub":"레인 싱클레어","unique":true,"hp":3,"atk":1,"atkStar":true,"thw":2,"thwStar":true,"cost":3,"res":"R","cls":"Justice","tr":["X-FORCE"],"traits":["엑스포스"],"text":"[star] <b>반응</b>: 울프스베인이 저지한 후, 카드 유형 하나를 선언하고, 그러고 나서 당신의 덱 맨 위 카드를 버립니다. 그 카드가 선언한 유형이라면, 그 카드를 당신의 손에 더해도 됩니다.","star":true},{"id":"40052","name":"열세 만회","en":"Even the Odds","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","req":"Y","cls":"Justice","tr":["THWART"],"traits":["저지"],"text":"요구 조건([energy]).\n<b>히어로 행동</b><i>(저지)</i>: 각 부가 음모에서 위협을 1[per_hero]만큼 제거합니다. 이렇게 격파된 부가 음모마다 빌런에게 피해 1점을 입힙니다.","link":"30014"},{"id":"40053","name":"팀 조사","en":"Team Investigation","type":"event","enc":false,"unique":false,"cost":2,"costStar":true,"res":"B","cls":"Justice","tr":[],"alliance":1,"traits":[],"text":"동맹. <i>(플레이어들은 이 카드의 비용을 함께 지불할 수 있습니다.)</i>\n<b>히어로 행동</b>: 부가 음모 하나에서 위협을 3[per_hero]만큼 제거합니다."},{"id":"40054","name":"경비병 제거","en":"* Take Out the Guards","type":"pside","enc":false,"unique":true,"cost":0,"start":4,"startStar":true,"res":"B","cls":"Justice","tr":[],"victory":0,"traits":[],"text":"승점 0.\n<b>격파될 때</b>: 각 플레이어는 플레이 영역에서 [[간부]]가 아닌 하수인 1장을 버려도 됩니다."},{"id":"40055","name":"엄호 태세","en":"Overwatch","type":"upgrade","enc":false,"unique":false,"cost":0,"res":"R","cls":"Justice","tr":[],"maxPer":1,"traits":[],"text":"음모에 장착합니다. 음모마다 최대 1장.\n<b>히어로 난입</b>: 저지로 인해 장착된 음모에서 위협이 제거될 때, 이 카드를 버림 → 다른 음모 하나에서 같은 양의 위협을 제거.","link":"30019"},{"id":"40056","name":"아틀라스 베어","en":"* Atlas Bear","type":"ally","enc":false,"sub":"슌콰","unique":true,"hp":3,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"B","cls":"Basic","tr":["POSSE","WAKANDA"],"traits":["패거리","와칸다"],"text":"<b>행동</b>: 아틀라스 베어를 소진 → 플레이어 덱 하나의 맨 위 카드를 봄. 그 카드가 이벤트라면, 아틀라스 베어에게 피해 1점을 입혀 그 카드를 소유자의 손에 더해도 됨."},{"id":"40057","name":"화이트 폭스","en":"* White Fox","type":"ally","enc":false,"sub":"아미 한","unique":true,"hp":3,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"Y","cls":"Basic","tr":["POSSE"],"traits":["패거리"],"text":"<b>반응</b>: 화이트 폭스가 당신의 덱 맨 위에서 버려진 후, 그녀를 당신의 조종하에 플레이 영역에 내려놓습니다."},{"id":"40058","name":"패거리","en":"The Posse","type":"event","enc":false,"unique":false,"cost":2,"res":"G","cls":"Basic","tr":["POSSE"],"maxDeck":1,"traits":["패거리"],"text":"덱마다 최대 1장.\n당신이 [[패거리]] 특성을 가진 캐릭터를 3명 이상 조종할 때만 플레이합니다.\n<b>히어로 행동</b>: 각 [[패거리]] 캐릭터가 입은 피해 1점을 치료하고 그 캐릭터들을 준비합니다."},{"id":"40059","name":"슈퍼파워 훈련","en":"* Superpower Training","type":"pside","enc":false,"unique":true,"cost":1,"start":3,"startStar":true,"res":"Y","cls":"Basic","tr":[],"victory":0,"traits":[],"text":"승점 0.\n<b>격파될 때</b>: 각 플레이어는 자신의 덱과 버린 더미에서 아이덴티티 전용 업그레이드 하나를 찾아 플레이 영역에 내려놓아도 됩니다. <i>(덱을 섞습니다.)</i>"},{"id":"40060","name":"안간힘","en":"Digging Deep","type":"resource","enc":false,"unique":false,"res":"G","cls":"Basic","tr":[],"traits":[],"text":"<b>반응</b>: 이 카드가 당신의 덱 맨 위에서 버려진 후, 이 카드를 당신의 손에 더합니다."},{"id":"40061","name":"에너지","en":"Energy","type":"resource","enc":false,"unique":false,"res":"YY","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01088"},{"id":"40062","name":"천재","en":"Genius","type":"resource","enc":false,"unique":false,"res":"BB","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01089"},{"id":"40063","name":"힘","en":"Strength","type":"resource","enc":false,"unique":false,"res":"RR","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01090"},{"id":"40064","name":"명사수","en":"Sharpshooter","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Basic","tr":["SKILL"],"maxPer":1,"traits":["기술"],"text":"플레이어마다 최대 1장. <b>히어로 난입</b>: 당신이 원거리 공격을 할 때, 당신의 덱 맨 위 카드를 버림 → 이렇게 버려진 자원 아이콘마다 이 공격은 피해 1점을 추가로 입힘."},{"id":"40065","name":"아마겟돈의 기억","en":"Memories of Armageddon","type":"obligation","enc":true,"set":"Domino","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b><i>니나 서먼 플레이어에게 이 카드를 줍니다.</i></b>\n당신의 아이덴티티에 인쇄된 문구 상자를 비어 있는 것으로 취급합니다 <i>([[특성]] 제외)</i>.\n<b>일상 행동</b>: 당신의 아이덴티티를 소진 → 아마겟돈의 기억을 버림."},{"id":"40066","name":"토파즈","en":"* Topaz","type":"minion","enc":true,"set":"Domino Nemesis","unique":true,"hp":3,"atk":2,"sch":1,"boost":3,"tr":["MUTANT"],"nemesis":true,"traits":["뮤턴트"],"text":"<b>공개될 때</b>: 조우 덱, 버린 조우 더미, 따로 놓아둔 영역에서 초능력 역류 1장을 찾아 당신의 아이덴티티에 장착합니다. <i>(덱을 섞습니다.)</i>\n<i>(도미노의 숙적 하수인.)</i>"},{"id":"40067","name":"운수 나쁜 날","en":"Not My Lucky Day","type":"side","enc":true,"set":"Domino Nemesis","unique":false,"boost":2,"start":3,"tr":[],"amplify":1,"traits":[],"text":"<b>공개될 때</b>: 각 플레이어는 피해 1점을 입거나, 이 카드에 위협을 2만큼 놓아야 합니다."},{"id":"40068","name":"프로토타입","en":"* Prototype","type":"minion","enc":true,"set":"Domino Nemesis","unique":true,"hp":1,"atk":2,"sch":2,"boost":2,"tr":["MUTANT"],"traits":["뮤턴트"],"text":"[star] 프로토타입은 자신에게 놓인 행운 카운터마다 생명력 +1을 받습니다.\n<b>공개될 때</b>: 당신의 아이덴티티가 입은 피해만큼 프로토타입에 행운 카운터를 놓습니다.","star":true},{"id":"40069","name":"초능력 역류","en":"Superpower Feedback","type":"attachment","enc":true,"set":"Domino Nemesis","unique":false,"boost":1,"tr":["CONDITION"],"traits":["상태"],"text":"당신의 아이덴티티에 장착합니다.\n<b>강제 반응</b>: 당신이 당신의 아이덴티티 또는 아이덴티티 전용 카드에 있는 능력을 해결한 후, 피해 1점을 입습니다.\n<b>일상 행동</b>: 당신의 손에서 아이덴티티 전용 카드 1장을 버림 → 이 카드를 버림."},{"id":"40070a","name":"아크라이트","en":"* Arclight","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":10,"hpStar":true,"atk":1,"sch":1,"tr":["BRUTE","MARAUDER"],"traits":["야만","머로더"],"text":"[star] <b>강제 난입</b>: 아크라이트가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 당신이 조종하는 캐릭터 하나를 혼란에 빠뜨립니다.\n• 아크라이트는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40070b","name":"아크라이트","en":"* Arclight","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":13,"hpStar":true,"atk":2,"sch":2,"tr":["BRUTE","MARAUDER"],"traits":["야만","머로더"],"text":"[star] <b>강제 난입</b>: 아크라이트가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 당신이 조종하는 캐릭터 중 저지 수치가 가장 높은 캐릭터를 혼란에 빠뜨립니다.\n• 아크라이트는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40071a","name":"블록버스터","en":"* Blockbuster","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":11,"hpStar":true,"atk":2,"sch":0,"tr":["BRUTE","MARAUDER"],"traits":["야만","머로더"],"text":"[star] <b>강제 난입</b>: 블록버스터가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 블록버스터에게 강인함 상태 카드를 줍니다.\n• 블록버스터는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40071b","name":"블록버스터","en":"* Blockbuster","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":14,"hpStar":true,"atk":3,"sch":1,"tr":["BRUTE","MARAUDER"],"traits":["야만","머로더"],"text":"[star] <b>강제 난입</b>: 블록버스터가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 블록버스터에게 강인함 상태 카드를 줍니다.\n• 블록버스터는 이 공격에서 공격 +2를 받고 이 공격은 압살을 얻습니다.","star":true},{"id":"40072a","name":"키메라","en":"* Chimera","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":11,"hpStar":true,"atk":1,"sch":1,"tr":["MARAUDER","PSIONIC"],"traits":["머로더","사이오닉"],"text":"[star] <b>강제 난입</b>: 키메라가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• [mental] 자원 1개를 소모합니다.\n• 키메라는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40072b","name":"키메라","en":"* Chimera","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":14,"hpStar":true,"atk":2,"sch":2,"tr":["MARAUDER","PSIONIC"],"traits":["머로더","사이오닉"],"text":"[star] <b>강제 난입</b>: 키메라가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• [mental][mental] 자원을 소모합니다.\n• 키메라는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40073a","name":"그레이크로우","en":"* Greycrow","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":9,"hpStar":true,"atk":1,"sch":1,"tr":["MARAUDER","MERCENARY"],"traits":["머로더","용병"],"text":"[star] <b>강제 난입</b>: 그레이크로우가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 당신이 조종하는 카드 중 비용이 가장 높은 카드 1장을 버립니다.\n• 그레이크로우는 이 공격 동안 공격 +X를 받습니다. X는 당신이 조종하는 카드 중 비용이 가장 높은 카드에 인쇄된 비용입니다.","star":true},{"id":"40073b","name":"그레이크로우","en":"* Greycrow","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":12,"hpStar":true,"atk":2,"sch":2,"tr":["MARAUDER","MERCENARY"],"traits":["머로더","용병"],"text":"[star] <b>강제 난입</b>: 그레이크로우가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 당신이 조종하는 카드 중 비용이 가장 높은 카드를 모두 버립니다.\n• 그레이크로우는 이 공격 동안 공격 +X를 받습니다. X는 당신이 조종하는 카드 중 비용이 가장 높은 카드에 인쇄된 비용입니다.","star":true},{"id":"40074a","name":"하푼","en":"* Harpoon","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":10,"hpStar":true,"atk":2,"sch":0,"tr":["BRUTE","MARAUDER"],"traits":["야만","머로더"],"text":"[star] <b>강제 난입</b>: 하푼이 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 간접 피해 2점을 입습니다.\n• 이 공격 동안 하푼에게 뒷면 강화 카드 1장을 추가로 줍니다.","star":true},{"id":"40074b","name":"하푼","en":"* Harpoon","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":13,"hpStar":true,"atk":3,"sch":1,"tr":["BRUTE","MARAUDER"],"traits":["야만","머로더"],"text":"[star] <b>강제 난입</b>: 하푼이 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 간접 피해 3점을 입습니다.\n• 이 공격 동안 하푼에게 뒷면 강화 카드 1장을 추가로 줍니다. 이 공격은 압살을 얻습니다.","star":true},{"id":"40075a","name":"립타이드","en":"* Riptide","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":9,"hpStar":true,"atk":1,"sch":1,"tr":["ASSASSIN","MARAUDER"],"traits":["암살자","머로더"],"text":"[star] <b>강제 난입</b>: 립타이드가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 주요 음모에 위협을 2만큼, 각 부가 음모에 위협을 1만큼 놓습니다.\n• 립타이드는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40075b","name":"립타이드","en":"* Riptide","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":12,"hpStar":true,"atk":2,"sch":2,"tr":["ASSASSIN","MARAUDER"],"traits":["암살자","머로더"],"text":"[star] <b>강제 난입</b>: 립타이드가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 주요 음모에 위협을 3만큼, 각 부가 음모에 위협을 1만큼 놓습니다.\n• 립타이드는 이 공격 동안 공격 +2를 받고, 이 공격은 원거리와 관통을 얻습니다.","star":true},{"id":"40076a","name":"버티고","en":"* Vertigo","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":9,"hpStar":true,"atk":0,"sch":2,"tr":["MARAUDER","MUTATE"],"traits":["머로더","변이체"],"text":"[star] <b>강제 난입</b>: 버티고가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 당신이 조종하는 캐릭터 하나를 기절시킵니다.\n• 버티고는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40076b","name":"버티고","en":"* Vertigo","type":"villain","enc":true,"set":"Marauders","unique":true,"hp":12,"hpStar":true,"atk":1,"sch":3,"tr":["MARAUDER","MUTATE"],"traits":["머로더","변이체"],"text":"[star] <b>강제 난입</b>: 버티고가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 당신이 조종하는 캐릭터 중 공격 수치가 가장 높은 캐릭터 하나를 기절시킵니다.\n• 버티고는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40077a","name":"똑똑","en":"Knock, Knock","type":"main","enc":true,"set":"Morlock Siege","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 머로더즈 A면 <i>(전문가 모드에서는 B면)</i>. 몰록 포위전 및 일반 조우 세트. 모듈식 조우 세트 2개 <i>(군용 장비 및 뮤턴트 학살자)</i>.\n<b>사전 준비</b>: 패주 환경을 플레이 영역에 내려놓습니다. 숨어! 배반 카드와 각 몰록 동료를 따로 놓아둡니다. 빌런들을 <i>(보지 않고)</i> 함께 섞어 빌런 덱을 만듭니다. 이 덱의 맨 위 카드는 플레이 중입니다."},{"id":"40077b","name":"똑똑","en":"Knock, Knock","type":"main","enc":true,"set":"Morlock Siege","unique":false,"start":1,"startStar":true,"target":6,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"[star] <b>강제 반응</b>: 빌런 페이즈의 1단계를 해결한 후, 이 카드에 노크 카운터를 1만큼 놓습니다. 이 카드에 노크 카운터가 3 이상 있다면, 스테이지 2A로 진행합니다.\n<b>패주 밑에 빌런이 3장 있다면, 플레이어들이 게임에서 승리합니다.</b>","star":true},{"id":"40078a","name":"뮤턴트 대학살","en":"Mutant Massacre","type":"main","enc":true,"set":"Morlock Siege","unique":false,"stage":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 플레이어는 따로 놓아둔 몰록 동료 1장을 자신의 조종하에 플레이 영역에 내려놓습니다(1인 게임이라면 대신 따로 놓아둔 몰록 동료 2장). 숨어! 배반 카드를 조우 덱에 섞어 넣습니다. 이전 스테이지가 노크 카운터에 의해 진행되었다면, 각 몰록 동료에게 강인함 상태 카드를 줍니다."},{"id":"40078b","name":"뮤턴트 대학살","en":"Mutant Massacre","type":"main","enc":true,"set":"Morlock Siege","unique":false,"start":0,"target":8,"targetStar":true,"esc":1,"escStar":true,"stage":2,"tr":[],"traits":[],"text":"<b>행동</b>: [[몰록]] 동료 하나를 소진 → 버린 조우 더미에서 숨어!를 조우 덱에 섞어 넣음.\n<b>패주 밑에 빌런이 3장 있다면, 플레이어들이 게임에서 승리합니다.\n이 스테이지가 완료되거나 플레이 중인 몰록 동료가 없다면, 플레이어들이 게임에서 패배합니다.</b>"},{"id":"40079","name":"몰록","en":"Morlock","type":"ally","enc":false,"unique":false,"hp":5,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"res":"B","cls":"Encounter","tr":["MORLOCK","MUTANT"],"victory":-1,"traits":["몰록","뮤턴트"],"text":"승점 -1.\n동료 제한 수에 포함되지 않습니다. 카드 능력으로 이 동료를 플레이 영역에서 제거할 수 없습니다.\n<b>강제 난입</b>: 적이 당신을 공격할 때, 그 적은 대신 당신이 조종하는 몰록 하나를 공격합니다."},{"id":"40080","name":"숨어!","en":"Hide!","type":"treachery","enc":true,"set":"Morlock Siege","unique":false,"surge":1,"tr":[],"traits":[],"text":"쇄도.\n<b>공개될 때</b>: [[몰록]] 동료 하나에게 강인함 상태 카드를 줍니다.\n<hr />\n[star] <b>강화</b>: [[몰록]] 동료 하나에게 강인함 상태 카드를 줍니다. 이번 활성화 동안 빌런에게 강화 카드 1장을 추가로 줍니다.","star":true,"boostStar":true},{"id":"40081a","name":"패주","en":"Routed","type":"environment","enc":true,"set":"Morlock Siege","unique":false,"tr":[],"traits":[],"text":"<b>일반 모드 전용.</b>\n이 카드 밑에 있는 카드는 플레이 중이 아닙니다.\n<b>강제 반응</b>: 빌런이 격파된 후, 그 빌런을 이 카드 밑에 놓습니다. 빌런 덱 맨 위 빌런과 같은 이름을 가진 각 하수인을 버립니다. <i>(그 빌런은 플레이 중입니다.)</i> 빌런이 플레이어 순서대로 각 플레이어를 상대로 활성화합니다."},{"id":"40081b","name":"패주","en":"Routed","type":"environment","enc":true,"set":"Morlock Siege","unique":false,"tr":[],"traits":[],"text":"<b>전문가 모드 전용.</b>\n이 카드 밑에 있는 카드는 플레이 중이 아닙니다. 빌런은 이 카드 밑에 있는 카드마다 반격 1을 얻습니다.\n<b>강제 반응</b>: 빌런이 격파된 후, 그 빌런을 이 카드 밑에 놓습니다. 빌런 덱 맨 위 빌런과 같은 이름을 가진 각 하수인을 버립니다. <i>(그 빌런은 플레이 중입니다.)</i> 빌런이 플레이어 순서대로 각 플레이어를 상대로 활성화합니다."},{"id":"40082","name":"분노로 강해진","en":"Bolstered by Wrath","type":"attachment","enc":true,"set":"Morlock Siege","unique":false,"boost":1,"plus":{"atk":1,"sch":1},"tr":["CONDITION"],"traits":["상태"],"text":"빌런에게 장착합니다.\n<b>히어로 행동</b>: 당신이 조종하는 캐릭터 하나를 소진하고 아무 유형의 자원을 X개 소모(X는 패주 밑에 있는 빌런의 수) → 이 카드를 버림.\n<hr />\n[star] <b>강화</b>: 이 카드는 강화 아이콘 +X개([boost])를 받습니다. X는 패주 밑에 있는 빌런의 수입니다.","star":true,"boostStar":true},{"id":"40083","name":"한계까지 몰림","en":"Pushed to the Limit","type":"attachment","enc":true,"set":"Morlock Siege","unique":false,"boost":3,"plus":{"atk":1},"tr":["CONDITION"],"traits":["상태"],"text":"빌런에게 장착합니다.\n패주 밑에 빌런이 정확히 1장 있는 동안, 장착된 빌런은 의연을 얻습니다.\n패주 밑에 빌런이 정확히 2장 있는 동안, 장착된 빌런은 견고를 얻습니다.\n<b>히어로 행동</b>: 장착된 빌런이 당신을 공격 → 이 카드를 버림."},{"id":"40084","name":"수단과 방법을 가리지 않고","en":"By Any Means","type":"side","enc":true,"set":"Morlock Siege","unique":false,"boost":3,"start":3,"hazard":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 패주 밑에 있는 빌런마다 이 카드에 위협을 1[per_hero]만큼 추가로 놓습니다."},{"id":"40085","name":"혼돈의 한가운데","en":"In the Midst of Chaos","type":"side","enc":true,"set":"Morlock Siege","unique":false,"boost":1,"start":3,"accel":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 패주 밑에 있는 빌런마다 이 카드에 위협을 1[per_hero]만큼 추가로 놓습니다."},{"id":"40086","name":"약탈은 쉽지 않아","en":"Maraudin' Ain't Easy","type":"side","enc":true,"set":"Morlock Siege","unique":false,"boost":2,"start":3,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 패주 밑에 있는 빌런마다 이 카드에 위협을 1[per_hero]만큼 추가로 놓습니다."},{"id":"40087","name":"영역 장악","en":"Territorial Control","type":"side","enc":true,"set":"Morlock Siege","unique":false,"boost":2,"start":4,"tr":[],"crisis":1,"traits":[],"text":"맹공. <i>(이 음모에 대한 기본 저지는 저지 대신 공격을 사용합니다.)</i>\n<b>공개될 때</b>: 패주 밑에 있는 빌런마다 이 카드에 위협을 1[per_hero]만큼 추가로 놓습니다."},{"id":"40088","name":"현장 복귀","en":"Back in Action","type":"treachery","enc":true,"set":"Morlock Siege","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 빌런에게 강인함 상태 카드를 줍니다. 패주 밑에 있는 빌런의 수만큼 주요 음모에 위협을 놓습니다.\n<hr />\n[star] <b>강화</b>: 당신이 몰록 동료를 조종하고 있다면, 그 동료에게 피해 1점을 입히거나 아무 유형의 자원을 1개 소모하는 것 중 하나를 선택합니다.","star":true,"boostStar":true},{"id":"40089","name":"약자 탐색","en":"Seek the Weak","type":"treachery","enc":true,"set":"Morlock Siege","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때(일상)</b>: 이 카드는 쇄도를 얻습니다.\n<b>공개될 때(히어로)</b>: 빌런이 당신을 공격합니다. 패주 밑에 빌런이 1장 이상 있다면, 이 공격은 압살을 얻습니다.\n<hr />\n[star] <b>강화</b>: 이번 활성화가 공격이라면, 그 공격은 압살을 얻습니다.","star":true,"boostStar":true},{"id":"40090","name":"중화기","en":"Heavy Armament","type":"attachment","enc":true,"set":"Military Grade","unique":false,"boost":3,"plus":{"atk":2},"tr":["WEAPON"],"traits":["무기"],"text":"공격 수치가 가장 높은 적에게 장착합니다.\n장착된 적은 반격 2를 얻습니다.\n<b>히어로 반응</b>: 당신이 장착된 적을 공격한 후, 같은 유형의 자원을 2개 소모 → 이 카드를 버림."},{"id":"40091","name":"티타늄 외골격","en":"Titanium Exoskeleton","type":"attachment","enc":true,"set":"Military Grade","unique":false,"boost":2,"tr":["ARMOR","TECH"],"traits":["갑옷","과학"],"text":"남은 생명력이 가장 적은 적에게 장착합니다.\n장착된 적은 한 번의 공격으로 피해를 2점보다 많이 입을 수 없습니다.\n<b>히어로 행동</b>: 아무 유형의 자원을 3개 소모하거나 장착된 적에게서 혼란 또는 기절 상태 카드 1장을 제거하는 것 중 하나를 선택 → 이 카드를 버림."},{"id":"40092","name":"억제 목걸이","en":"Inhibitor Collar","type":"attachment","enc":true,"set":"Military Grade","unique":false,"boost":1,"plus":{"atk":-1},"tr":["TECH"],"traits":["과학"],"text":"당신의 아이덴티티에 장착합니다.\n당신의 아이덴티티에 인쇄된 문구 상자는 비어 있는 것으로 취급합니다<i>(특성은 제외)</i>.\n<b>행동</b>: 당신이 조종하는 캐릭터 하나를 소진하거나 피해 3점을 입는 것 중 하나를 선택 → 이 카드를 버림. 모든 플레이어가 이 능력을 사용할 수 있습니다."},{"id":"40093","name":"상원의원의 지지","en":"The Senator's Support","type":"side","enc":true,"set":"Military Grade","unique":false,"boost":2,"start":3,"tr":[],"amplify":1,"hinder":1,"hinderStar":true,"traits":[],"text":"교란 1[per_hero].\n<b>격파될 때</b>: 시작 플레이어는 장착 카드가 버려질 때까지 조우 덱 맨 위에서 카드를 버리고 그 카드를 공개합니다."},{"id":"40094","name":"아크라이트","en":"* Arclight","type":"minion","enc":true,"set":"Mutant Slayers","unique":true,"hp":5,"atk":1,"sch":1,"boost":1,"retaliate":1,"tr":["BRUTE","MARAUDER"],"traits":["야만","머로더"],"text":"반격 1.\n[star] <b>강제 난입</b>: 아크라이트가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 당신이 조종하는 캐릭터 하나를 혼란에 빠뜨립니다.\n• 아크라이트는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40095","name":"블록버스터","en":"* Blockbuster","type":"minion","enc":true,"set":"Mutant Slayers","unique":true,"hp":5,"atk":2,"sch":0,"boost":2,"tr":["BRUTE","MARAUDER"],"guard":1,"traits":["야만","머로더"],"text":"경호.\n[star] <b>강제 난입</b>: 블록버스터가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 블록버스터에게 강인함 상태 카드를 줍니다.\n• 블록버스터는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40096","name":"키메라","en":"* Chimera","type":"minion","enc":true,"set":"Mutant Slayers","unique":true,"hp":5,"atk":1,"sch":1,"boost":3,"tr":["MARAUDER","PSIONIC"],"patrol":1,"traits":["머로더","사이오닉"],"text":"순찰.\n[star] <b>강제 난입</b>: 키메라가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• [mental] 자원 1개를 소모합니다.\n• 키메라는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40097","name":"그레이크로우","en":"* Greycrow","type":"minion","enc":true,"set":"Mutant Slayers","unique":true,"hp":4,"atk":1,"sch":1,"boost":3,"retaliate":1,"tr":["MARAUDER","MERCENARY"],"traits":["머로더","용병"],"text":"반격 1.\n[star] <b>강제 난입</b>: 그레이크로우가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 당신이 조종하는 카드 중 비용이 가장 높은 카드 1장을 버립니다.\n• 그레이크로우는 이 공격 동안 공격 +X를 받습니다. X는 당신이 조종하는 카드 중 비용이 가장 높은 카드에 인쇄된 비용입니다.","star":true},{"id":"40098","name":"하푼","en":"* Harpoon","type":"minion","enc":true,"set":"Mutant Slayers","unique":true,"hp":5,"atk":2,"sch":0,"boost":1,"tr":["BRUTE","MARAUDER"],"guard":1,"traits":["야만","머로더"],"text":"경호.\n[star] <b>강제 난입</b>: 하푼이 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 간접 피해 2점을 입습니다.\n• 하푼은 이 공격 동안 공격 +2를 받고, 이 공격은 관통을 얻습니다.","star":true},{"id":"40099","name":"립타이드","en":"* Riptide","type":"minion","enc":true,"set":"Mutant Slayers","unique":true,"hp":4,"atk":1,"sch":1,"boost":1,"tr":["ASSASSIN","MARAUDER"],"patrol":1,"traits":["암살자","머로더"],"text":"순찰.\n[star] <b>강제 난입</b>: 립타이드가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 주요 음모에 위협을 2만큼, 각 부가 음모에 위협을 1만큼 놓습니다.\n• 립타이드는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40100","name":"버티고","en":"* Vertigo","type":"minion","enc":true,"set":"Mutant Slayers","unique":true,"hp":4,"atk":0,"sch":1,"boost":2,"tr":["MARAUDER","MUTATE"],"guard":1,"traits":["머로더","변이체"],"text":"경호.\n[star] <b>강제 난입</b>: 버티고가 당신이나 당신이 조종하는 동료를 공격할 때, 다음 중 하나를 선택합니다.\n• 당신이 조종하는 캐릭터 하나를 기절시킵니다.\n• 버티고는 이 공격 동안 공격 +2를 받습니다.","star":true},{"id":"40101","name":"뮤턴트 학살자","en":"Mutant Slayers","type":"side","enc":true,"set":"Mutant Slayers","unique":false,"boost":2,"start":3,"tr":[],"traits":[],"text":"각 [[머로더]] 하수인은 속공을 얻습니다.\n<b>공개될 때</b>: 다음 특성 중 1개 이상을 가진 플레이 중인 캐릭터마다 이 카드에 위협을 1만큼 추가로 놓습니다: [[뮤턴트]], [[엑스팩터]], [[엑스포스]], [[엑스맨]]."},{"id":"40102","name":"사업상의 굴레","en":"Bound by Business","type":"treachery","enc":true,"set":"Mutant Slayers","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 플레이 중인 카드와 같은 이름을 가지지 않은 [[머로더]] 하수인이 버려질 때까지 조우 덱에서 카드를 버립니다. 그 하수인을 당신과 교전 중인 채로 플레이 영역에 내려놓습니다."},{"id":"40103a","name":"도망쳐야 해","en":"Gotta Get Away","type":"main","enc":true,"set":"On the Run","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 머로더즈 A면 <i>(전문가 모드에서는 B면)</i>. 도주 중, 뮤턴트 학살자 및 일반 조우 세트. 모듈식 조우 세트 2개 <i>(군용 장비 및 내스티 보이즈)</i>.\n<b>사전 준비</b>: 무작위 [[머로더]] 빌런 1장을 플레이 영역에 내려놓습니다. 그 빌런과 같은 이름을 가진 하수인과 다른 각 빌런을 게임에서 제거합니다. 호프를 붙잡은 자 장착 카드를 [[자신만만]] 면이 위로 오게 하여 빌런에게 장착합니다."},{"id":"40103b","name":"도망쳐야 해","en":"Gotta Get Away","type":"main","enc":true,"set":"On the Run","unique":false,"start":1,"startStar":true,"target":8,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"각 [[머로더]] 하수인은 의연을 얻습니다.\n<b>공개될 때</b>: 각 플레이어는 조우 덱에서 [[머로더]] 하수인 1장을 찾아 자신과 교전 중인 채로 플레이 영역에 내려놓습니다. <i>(덱을 섞습니다.)</i>\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"40104a","name":"호프와 함께 탈출","en":"Escaping with Hope","type":"main","enc":true,"set":"On the Run","unique":false,"stage":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 플레이어는 조우 덱과 버린 조우 더미에서 [[머로더]] 하수인 1장을 찾아 자신과 교전 중인 채로 플레이 영역에 내려놓습니다. <i>(덱을 섞습니다.)</i> 각 [[머로더]] 적에게 강인함 상태 카드를 줍니다."},{"id":"40104b","name":"호프와 함께 탈출","en":"Escaping with Hope","type":"main","enc":true,"set":"On the Run","unique":false,"start":1,"startStar":true,"target":9,"targetStar":true,"esc":2,"escStar":true,"stage":2,"tr":[],"traits":[],"text":"각 [[머로더]] 하수인은 경호와 의연을 얻습니다. 전문가 모드에서는, 빌런이 의연을 얻습니다.\n<b>빌런이 격파되면, 플레이어들이 게임에서 승리합니다.</b>\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"40105a","name":"호프를 붙잡은 자","en":"Hope's Captor","type":"attachment","enc":true,"set":"On the Run","unique":false,"tr":["CONFIDENT"],"permanent":1,"traits":["자신만만"],"text":"영속.\n[star] <b>강제 난입</b>: 빌런이 당신을 공격하려 할 때, [[머로더]] 하수인이 당신과 교전 중이라면 빌런은 대신 암약합니다.\n<b>강제 난입</b>: 빌런이 격파되려 할 때, 대신 장착된 빌런의 생명력을 인쇄된 생명력 수치로 재설정합니다. 이 카드를 뒤집어 공개합니다.","star":true},{"id":"40105b","name":"호프를 붙잡은 자","en":"Hope's Captor","type":"attachment","enc":true,"set":"On the Run","unique":false,"plus":{"atk":1,"sch":1},"tr":["DESPERATE"],"permanent":1,"traits":["절박"],"text":"영속.\n빌런은 생명력 +6[per_hero]를 받습니다.\n<b>공개될 때</b>: 주요 음모를 스테이지 2A로 진행합니다. 이 효과는 무효화할 수 없습니다.\n[star] <b>강제 난입</b>: 빌런이 당신을 공격하려 할 때, [[머로더]] 하수인이 당신과 교전 중이라면 빌런은 대신 암약합니다.","star":true},{"id":"40106","name":"잡동사니 속에 숨다","en":"Hidden in the Clutter","type":"attachment","enc":true,"set":"On the Run","unique":false,"boost":2,"tr":["CONDITION"],"traits":["상태"],"text":"남은 생명력이 가장 적은 적에게 장착합니다.\n<b>강제 난입</b>: 장착된 적에게 피해가 입혀지려 할 때, 대신 그 피해를 이 카드에 놓습니다. 이 카드에 피해가 3점 이상 있다면, 장착된 적은 방금 이 카드에 놓인 피해를 입힌 플레이어를 공격합니다. 그러고 나서 이 카드를 버립니다."},{"id":"40107","name":"애용하는 무기","en":"Favored Weapon","type":"attachment","enc":true,"set":"On the Run","unique":false,"plus":{"atk":1},"tr":["WEAPON"],"traits":["무기"],"text":"그레이크로우 또는 하푼에게 장착합니다. 그럴 수 없다면, 공격 수치가 가장 낮은 [[머로더]] 적에게 장착합니다.\n[star] 장착된 적의 공격은 압살, 관통, 원거리를 얻습니다.\n<b>히어로 반응</b>: 당신의 히어로가 장착된 적의 공격에 대해 방어하고 피해를 입지 않은 후 → 이 카드를 버림.","star":true},{"id":"40108","name":"매복 기습","en":"Bushwhack","type":"side","enc":true,"set":"On the Run","unique":false,"boost":3,"start":1,"hazard":1,"tr":[],"traits":[],"text":"<b>격파될 때</b>: 이 음모를 격파한 플레이어는 조우 덱과 버린 조우 더미에서 [[머로더]] 하수인 1장을 찾아 자신과 교전 중인 채로 플레이 영역에 내려놓습니다. <i>(덱을 섞습니다.)</i>"},{"id":"40109","name":"순수한 힘","en":"Pure Force","type":"side","enc":true,"set":"On the Run","unique":false,"boost":3,"start":4,"accel":1,"tr":[],"traits":[],"text":"블록버스터가 플레이 중인 동안, 이 음모는 위기 아이콘([crisis])을 얻습니다.\n키메라가 플레이 중인 동안, 이 음모는 증폭 아이콘([amplify])을 얻습니다."},{"id":"40110","name":"현기증 나는 묘기","en":"Dizzying Deeds","type":"treachery","enc":true,"set":"On the Run","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신이 조종하는 캐릭터 하나를 소진합니다. 다음 적이 플레이 중이라면:\n• 아크라이트 — 당신이 조종하는 캐릭터 하나를 기절시킵니다.\n• 립타이드 — 간접 피해 3점을 입습니다.\n• 버티고 — 당신이 조종하는 캐릭터 하나를 혼란에 빠뜨립니다."},{"id":"40111","name":"태그 팀","en":"Tag Team","type":"treachery","enc":true,"set":"On the Run","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 다음 중 하나를 선택합니다.\n• 당신과 교전 중인 각 [[머로더]] 하수인이 당신을 상대로 활성화합니다.\n• 조우 덱 맨 위에서 카드 7장을 버립니다. 버린 조우 더미에서 가장 위에 있는 [[머로더]] 하수인을 당신과 교전 중인 채로 플레이 영역에 내려놓습니다."},{"id":"40112","name":"고저스 조지","en":"* Gorgeous George","type":"minion","enc":true,"set":"Nasty Boys","unique":true,"hp":4,"atk":2,"sch":1,"boost":1,"tr":["NASTY BOY"],"teamwork":"NASTY BOY","traits":["내스티 보이"],"text":"팀워크 ([[내스티 보이]]).\n[star] <b>강제 난입</b>: 고저스 조지가 당신을 공격할 때, 당신이 조종하는 캐릭터 하나를 소진합니다.\n<hr />\n[star] <b>강화</b>: 당신이 조종하는 캐릭터 하나를 소진합니다.","star":true,"boostStar":true},{"id":"40113","name":"헤어백","en":"* Hairbag","type":"minion","enc":true,"set":"Nasty Boys","unique":true,"hp":3,"atk":2,"sch":1,"boost":2,"surge":1,"tr":["NASTY BOY"],"teamwork":"NASTY BOY","traits":["내스티 보이"],"text":"쇄도. 팀워크 ([[내스티 보이]]).\n<hr />\n[star] <b>강화</b>: 이번 활성화 후, 헤어백을 조우 덱에 섞어 넣습니다.","star":true,"boostStar":true},{"id":"40114","name":"램로드","en":"* Ramrod","type":"minion","enc":true,"set":"Nasty Boys","unique":true,"hp":4,"atk":2,"sch":1,"boost":1,"retaliate":1,"tr":["NASTY BOY"],"teamwork":"NASTY BOY","traits":["내스티 보이"],"text":"반격 1. 팀워크 ([[내스티 보이]]).\n[star] 램로드의 공격은 관통을 얻습니다.\n<hr />\n[star] <b>강화</b>: 빌런이 공격 중이라면, 이 공격은 관통을 얻습니다.","star":true,"boostStar":true},{"id":"40115","name":"럭커스","en":"* Ruckus","type":"minion","enc":true,"set":"Nasty Boys","unique":true,"hp":3,"atk":1,"sch":2,"boost":1,"tr":["NASTY BOY"],"teamwork":"NASTY BOY","traits":["내스티 보이"],"text":"팀워크 ([[내스티 보이]]).\n<b>공개될 때</b>: 당신이 조종하는 각 캐릭터를 기절시킵니다.\n<hr />\n[star] <b>강화</b>: 당신은 기절합니다.","star":true,"boostStar":true},{"id":"40116","name":"슬랩","en":"* Slab","type":"minion","enc":true,"set":"Nasty Boys","unique":true,"hp":5,"atk":1,"sch":1,"boost":2,"tr":["NASTY BOY"],"toughness":1,"teamwork":"NASTY BOY","traits":["내스티 보이"],"text":"팀워크 ([[내스티 보이]]). 강인.\n[star] <b>강제 난입</b>: 슬랩이 공격할 때, 슬랩에게 성장 카운터를 1만큼 놓습니다. 슬랩은 이 공격 동안 자신에게 놓인 성장 카운터마다 공격 +1을 받습니다.","star":true},{"id":"40117","name":"거칠게 나가기","en":"Get Nasty","type":"side","enc":true,"set":"Nasty Boys","unique":false,"boost":3,"start":3,"tr":[],"traits":[],"text":"각 하수인은 공격 +1을 받습니다.\n<b>공개될 때</b>: 플레이 중인 하수인마다 이 카드에 위협을 1만큼 놓습니다(각 [[내스티 보이]]마다는 대신 2만큼). 조우 덱과 버린 조우 더미에서 [[내스티 보이]] 하수인 1장을 찾아 공개합니다. <i>(덱을 섞습니다.)</i>"},{"id":"40118","name":"저거노트","en":"* Juggernaut","type":"villain","enc":true,"set":"Juggernaut","unique":true,"hp":18,"hpStar":true,"atk":2,"sch":1,"stage":1,"tr":["BRUTE"],"traits":["야만"],"text":"[star] 저거노트는 이 카드에 놓인 기세 카운터마다 공격 +1을 받습니다.\n<b>공개될 때</b>: 이 카드에 기세 카운터를 1만큼 놓습니다. 저거노트에게 강인함 상태 카드를 줍니다.","star":true},{"id":"40119","name":"저거노트","en":"* Juggernaut","type":"villain","enc":true,"set":"Juggernaut","unique":true,"hp":21,"hpStar":true,"atk":3,"sch":1,"stage":2,"tr":["BRUTE"],"traits":["야만"],"text":"[star] 저거노트는 이 카드에 놓인 기세 카운터마다 공격 +1을 받습니다.\n<b>공개될 때</b>: 이 카드에 기세 카운터를 1만큼 놓습니다. 드러난 저거노트가 플레이 중이라면, 그 카드를 뒤집습니다. 그렇지 않다면, 저거노트에게 강인함 상태 카드를 줍니다.","star":true},{"id":"40120","name":"저거노트","en":"* Juggernaut","type":"villain","enc":true,"set":"Juggernaut","unique":true,"hp":25,"hpStar":true,"atk":4,"sch":2,"stage":3,"tr":["BRUTE"],"traits":["야만"],"text":"[star] 저거노트는 이 카드에 놓인 기세 카운터마다 공격 +1을 받습니다.\n<b>공개될 때</b>: 조우 덱과 버린 조우 더미에서 거센 기세를 찾아 공개합니다. <i>(덱을 섞습니다.)</i> 드러난 저거노트가 플레이 중이라면, 그 카드를 뒤집습니다. 그렇지 않다면, 저거노트에게 강인함 상태 카드를 줍니다.","star":true},{"id":"40121a","name":"멈출 수 없는 저거노트","en":"The Unstoppable Juggernaut","type":"main","enc":true,"set":"Juggernaut","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 저거노트 (I) 및 저거노트 (II) <i>(전문가 모드에서는 대신 저거노트 (II) 및 저거노트 (III))</i>. 저거노트, 호프 서머스 및 일반 조우 세트. 모듈식 조우 세트 1개 <i>(블랙 톰 캐시디)</i>.\n<b>사전 준비</b>: 저거노트 헬멧을 저거노트에게 장착합니다. 호프 서머스를 시작 플레이어의 조종하에 플레이 영역에 내려놓습니다."},{"id":"40121b","name":"멈출 수 없는 저거노트","en":"The Unstoppable Juggernaut","type":"main","enc":true,"set":"Juggernaut","unique":false,"start":1,"startStar":true,"target":7,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"[star] <b>강제 난입</b>: 이 음모가 완료되려 할 때, 대신 다음을 각각 수행합니다.\n1. 이 카드에서 모든 위협을 제거합니다.\n2. 드러난 저거노트가 플레이 중이라면, 그 카드를 뒤집습니다.\n3. 저거노트에게 기세 카운터를 1만큼 놓습니다.\n4. 저거노트가 플레이어 순서대로 각 플레이어를 공격합니다<i>(그 플레이어가 일상 형태라도)</i>.","star":true},{"id":"40122a","name":"저거노트 헬멧","en":"* Juggernaut's Helmet","type":"attachment","enc":true,"set":"Juggernaut","unique":true,"tr":["ARMOR"],"permanent":1,"traits":["갑옷"],"text":"영속. 저거노트에게 장착합니다.\n저거노트는 견고를 얻고, 저거노트의 공격은 압살을 얻습니다.\n<b>히어로 행동</b>: 같은 유형의 자원을 3개 소모 → 저거노트에게서 모든 기세 카운터를 제거. 이 카드를 뒤집음."},{"id":"40122b","name":"드러난 저거노트","en":"Juggernaut Exposed","type":"attachment","enc":true,"set":"Juggernaut","unique":false,"tr":[],"permanent":1,"traits":[],"text":"영속. 저거노트에게 장착합니다.\n저거노트는 [mental] 자원이 인쇄된 각 카드로부터 피해를 1점 추가로 입습니다.\n[star] <b>강제 반응</b>: 저거노트가 암약한 후, 저거노트에게 기세 카운터를 1만큼 놓습니다. 이 카드를 뒤집습니다.","star":true},{"id":"40123","name":"거센 기세","en":"Head of Steam","type":"attachment","enc":true,"set":"Juggernaut","unique":false,"boost":3,"tr":[],"traits":[],"text":"저거노트는 반격 X를 얻습니다. X는 저거노트에게 놓인 기세 카운터의 수입니다.\n<b>공개될 때</b>: 거센 기세를 저거노트에게 장착하고 저거노트에게 기세 카운터를 1만큼 놓습니다.\n<b>히어로 반응</b>: 저거노트가 당신을 공격한 후, 그 공격으로 입힌 피해 1점마다 자원을 1개 소모 → 이 카드를 버림."},{"id":"40124","name":"기세 올리기","en":"Building Momentum","type":"side","enc":true,"set":"Juggernaut","unique":false,"boost":2,"start":3,"startStar":true,"accel":2,"tr":[],"traits":[],"text":"<b>히어로 반응</b>: 당신이 저거노트의 공격에 대해 방어한 후, 이 음모에서 위협을 1만큼 제거합니다."},{"id":"40125","name":"정면 돌파","en":"Breakthrough","type":"treachery","enc":true,"set":"Juggernaut","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 다음 중 하나를 선택합니다.\n• 저거노트의 공격만큼 피해를 입습니다.\n• 당신이 조종하는 업그레이드나 지원 중 비용이 가장 높은 카드 1장을 버립니다."},{"id":"40126","name":"깔아뭉개기","en":"Flatten","type":"treachery","enc":true,"set":"Juggernaut","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 저거노트의 공격만큼 피해를 입거나 저거노트에게 기세 카운터를 1만큼 놓는 것 중 하나를 선택합니다.\n<hr />\n[star] <b>강화</b>: 저거노트에게 강인함 상태 카드를 줍니다.","star":true,"boostStar":true},{"id":"40127","name":"지면 강타","en":"Ground Pound","type":"treachery","enc":true,"set":"Juggernaut","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 플레이어들은 그룹으로서 저거노트의 공격만큼 간접 피해를 입습니다.\n<hr />\n[star] <b>강화</b>: 간접 피해 1점을 입습니다.","star":true,"boostStar":true},{"id":"40128","name":"마구 짓밟기","en":"Trample","type":"treachery","enc":true,"set":"Juggernaut","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때(일상)</b>: 간접 피해 2점을 입습니다.\n<b>공개될 때(히어로)</b>: 저거노트가 남은 생명력이 가장 적은 동료를 공격합니다.\n<hr />\n[star] <b>강화</b>: 당신이 조종하는 동료 하나에게 피해 1점을 입힙니다.","star":true,"boostStar":true},{"id":"40129","name":"사이토락의 화신","en":"Cyttorak's Exemplar","type":"treachery","enc":true,"set":"Juggernaut","unique":false,"boost":3,"tr":[],"traits":[],"text":"전문가 모드에서는, 이 카드가 진척 1을 얻습니다.\n<b>공개될 때</b>: 드러난 저거노트가 플레이 중이라면, 그 카드를 뒤집고 저거노트에게 기세 카운터를 1만큼 놓습니다. 그렇지 않다면, 저거노트의 공격만큼 주요 음모에 위협을 놓습니다."},{"id":"40130","name":"호프 서머스","en":"* Hope Summers","type":"ally","enc":false,"unique":true,"hp":3,"res":"B","cls":"Encounter","tr":["PSIONIC","X-FORCE","X-MEN"],"setupCard":1,"traits":["사이오닉","엑스포스","엑스맨"],"text":"사전 준비. 시작 플레이어가 호프 서머스를 조종합니다. 호프 서머스는 당신의 동료 제한에 포함되지 않습니다.\n[star] 호프 서머스의 기본 저지와 기본 공격은 당신의 히어로의 저지 및 공격과 같습니다.\n<b>호프 서머스가 플레이 영역을 떠나면, 플레이어들은 게임에서 패배합니다.</b>","star":true},{"id":"40131","name":"사로잡힌 호프","en":"Captive Hope","type":"side","enc":true,"set":"Hope Summers","unique":false,"boost":3,"start":3,"startStar":true,"accel":1,"tr":[],"traits":[],"text":"호프 서머스는 준비할 수 없습니다.\n<b>공개될 때</b>: 호프 서머스를 소진합니다."},{"id":"40132","name":"블랙 톰 캐시디","en":"* Black Tom Cassidy","type":"minion","enc":true,"set":"Black Tom Cassidy","unique":true,"hp":6,"atk":1,"sch":1,"boost":3,"tr":["CRIMINAL","ELITE"],"villainous":1,"traits":["범죄자","간부"],"text":"악당.\n블랙 톰 캐시디는 기어다니는 버드나무가 플레이 영역에 있는 동안 피해를 입을 수 없습니다.\n<b>공개될 때</b>: 조우 덱과 버린 조우 더미에서 기어다니는 버드나무 1장을 찾아 당신과 교전 중인 채로 플레이 영역에 내려놓습니다. <i>(섞습니다.)</i>"},{"id":"40133","name":"기어다니는 버드나무","en":"Creeping Willow","type":"minion","enc":true,"set":"Black Tom Cassidy","unique":false,"hp":3,"atk":1,"sch":0,"boost":1,"tr":["WOOD"],"guard":1,"quickstrike":1,"traits":["나무"],"text":"경호. 속공.\n[star] <b>강제 반응</b>: 기어다니는 버드나무가 공격하여 캐릭터에게 피해를 입힌 후, 그 캐릭터를 기절시킵니다.\n<hr />\n[star] <b>강화</b>: 당신은 기절합니다.","star":true,"boostStar":true},{"id":"40134","name":"돈벌이","en":"Making Green","type":"side","enc":true,"set":"Black Tom Cassidy","unique":false,"boost":2,"start":2,"hazard":1,"tr":[],"hinder":2,"hinderStar":true,"traits":[],"text":"교란 2[per_hero].\n각 기어다니는 버드나무는 쇄도를 얻습니다."},{"id":"40135","name":"호된 매질","en":"A Sound Thrashing","type":"treachery","enc":true,"set":"Black Tom Cassidy","unique":false,"boost":3,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 기어다니는 버드나무가 자신과 교전 중인 플레이어를 공격합니다 <i>(그 플레이어가 일상 형태여도 공격합니다)</i>. 당신이 이렇게 공격받지 않았다면, 조우 덱과 버린 조우 더미에서 기어다니는 버드나무 1장을 찾아 공개합니다. <i>(섞습니다.)</i>"},{"id":"40136","name":"미스터 시니스터","en":"* Mister Sinister","type":"villain","enc":true,"set":"Mister Sinister","unique":true,"hp":14,"hpStar":true,"atk":1,"sch":2,"stage":1,"tr":["GENIUS"],"traits":["천재"],"text":"<b>강제 반응</b>: 미스터 시니스터에게 상태 카드가 놓인 후, 주요 음모에 위협을 1만큼 놓습니다."},{"id":"40137","name":"미스터 시니스터","en":"* Mister Sinister","type":"villain","enc":true,"set":"Mister Sinister","unique":true,"hp":17,"hpStar":true,"atk":2,"sch":2,"stage":2,"tr":["GENIUS"],"traits":["천재"],"text":"<b>공개될 때</b>: 주요 음모에 위협을 1[per_hero]만큼 놓습니다 (미스터 시니스터에게 [[슈퍼파워]] 장착 카드가 2장 미만이라면 대신 2[per_hero]만큼).\n<b>강제 반응</b>: 미스터 시니스터에게 상태 카드가 놓인 후, 주요 음모에 위협을 2만큼 놓습니다."},{"id":"40138","name":"미스터 시니스터","en":"* Mister Sinister","type":"villain","enc":true,"set":"Mister Sinister","unique":true,"hp":21,"hpStar":true,"atk":2,"sch":3,"stage":3,"tr":["GENIUS"],"traits":["천재"],"text":"<b>공개될 때</b>: 주요 음모에 위협을 2[per_hero]만큼 놓습니다 (미스터 시니스터에게 [[슈퍼파워]] 장착 카드가 2장 미만이라면 대신 3[per_hero]만큼).\n<b>강제 반응</b>: 미스터 시니스터에게 상태 카드가 놓인 후, 주요 음모에 위협을 3만큼 놓습니다."},{"id":"40139a","name":"사악한 의도","en":"Sinister Intent","type":"main","enc":true,"set":"Mister Sinister","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 미스터 시니스터 (I), 미스터 시니스터 (II) <i>(전문가 모드에서는 대신 미스터 시니스터 (II), 미스터 시니스터 (III))</i>. 미스터 시니스터, 비행, 괴력, 텔레파시, 호프 서머스 및 일반 조우 세트. 모듈식 조우 세트 하나 <i>(내스티 보이즈)</i>.\n<b>사전 준비</b>: 비행, 괴력, 텔레파시 조우 세트를 따로 놓아둡니다. 호프 서머스를 시작 플레이어가 조종하는 상태로 플레이 영역에 내려놓습니다."},{"id":"40139b","name":"사악한 의도","en":"Sinister Intent","type":"main","enc":true,"set":"Mister Sinister","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 무작위로 스테이지 2 하나를 게임에서 제거합니다. 그러고 나서 무작위 스테이지 2A로 진행합니다."},{"id":"40140a","name":"사악한 실험","en":"Sinister Experiment","type":"main","enc":true,"set":"Mister Sinister","unique":false,"stage":2,"tr":[],"traits":[]},{"id":"40140b","name":"이륙","en":"Taking Off","type":"main","enc":true,"set":"Mister Sinister","unique":false,"start":1,"startStar":true,"target":5,"targetStar":true,"esc":2,"escStar":true,"stage":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 미스터 시니스터에게 비행 장착 카드를 장착하고, 나머지 비행 조우 세트를 조우 덱에 섞어 넣습니다.\n<b>완료될 때</b>: 다른 스테이지 2A로 진행합니다. 그럴 수 없다면, 스테이지 3A로 진행합니다."},{"id":"40141a","name":"사악한 실험","en":"Sinister Experiment","type":"main","enc":true,"set":"Mister Sinister","unique":false,"stage":2,"tr":[],"traits":[],"link":"40140a"},{"id":"40141b","name":"벌크업","en":"Bulking Up","type":"main","enc":true,"set":"Mister Sinister","unique":false,"start":1,"startStar":true,"target":5,"targetStar":true,"esc":2,"escStar":true,"stage":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 미스터 시니스터에게 괴력 장착 카드를 장착하고, 나머지 괴력 조우 세트를 조우 덱에 섞어 넣습니다.\n<b>완료될 때</b>: 다른 스테이지 2A로 진행합니다. 그럴 수 없다면, 스테이지 3A로 진행합니다."},{"id":"40142a","name":"사악한 실험","en":"Sinister Experiment","type":"main","enc":true,"set":"Mister Sinister","unique":false,"stage":2,"tr":[],"traits":[],"link":"40140a"},{"id":"40142b","name":"집중","en":"Focusing In","type":"main","enc":true,"set":"Mister Sinister","unique":false,"start":1,"startStar":true,"target":5,"targetStar":true,"esc":2,"escStar":true,"stage":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 미스터 시니스터에게 텔레파시 장착 카드를 장착하고, 나머지 텔레파시 조우 세트를 조우 덱에 섞어 넣습니다.\n<b>완료될 때</b>: 다른 스테이지 2A로 진행합니다. 그럴 수 없다면, 스테이지 3A로 진행합니다."},{"id":"40143a","name":"사악한 목적","en":"Sinister Ends","type":"main","enc":true,"set":"Mister Sinister","unique":false,"stage":3,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 플레이어에게 뒷면 조우 카드 1장을 나누어 줍니다."},{"id":"40143b","name":"사악한 목적","en":"Sinister Ends","type":"main","enc":true,"set":"Mister Sinister","unique":false,"start":0,"target":7,"targetStar":true,"esc":1,"escStar":true,"stage":3,"tr":[],"traits":[],"text":"<b>강제 난입</b>: 미스터 시니스터가 공격할 때, 그는 대신 호프 서머스를 공격합니다. <i>(다른 캐릭터가 그 공격을 방어할 수 있습니다.)</i>\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"40144","name":"시니스터의 변장","en":"Sinister Disguise","type":"attachment","enc":true,"set":"Mister Sinister","unique":false,"boost":2,"tr":["CONDITION"],"traits":["상태"],"text":"미스터 시니스터에게 장착합니다.\n<b>강제 난입</b>: 플레이어가 미스터 시니스터에게 피해를 입히려 할 때, 그 플레이어는 [mental][mental] 자원을 소모할 수 있습니다. 그렇게 하지 않으면, 그 플레이어는 대신 남은 생명력이 가장 적은 아군 캐릭터에게 그 피해를 입힙니다. 이 카드를 버립니다 <i>(자원을 소모했는지와 관계없이)</i>."},{"id":"40145","name":"시니스터 병사","en":"Sinister Soldier","type":"minion","enc":true,"set":"Mister Sinister","unique":false,"hp":5,"atk":1,"sch":1,"tr":["CLONE"],"traits":["클론"],"text":"[star] 시니스터 병사는 미스터 시니스터에게 장착된 [[슈퍼파워]] 장착 카드마다 음모 +1과 공격 +1을 받습니다.\n<hr />\n[star] <b>강화</b>: 이번 활성화에서, 미스터 시니스터는 자신에게 장착된 [[슈퍼파워]] 장착 카드마다 음모 +1과 공격 +1을 받습니다.","star":true,"boostStar":true},{"id":"40146","name":"순간이동으로 사라짐","en":"Teleported Away","type":"side","enc":true,"set":"Mister Sinister","unique":false,"boost":2,"start":3,"tr":[],"crisis":1,"hinder":1,"hinderStar":true,"traits":[],"text":"교란 1[per_hero].\n미스터 시니스터는 피해를 입을 수 없습니다.\n<b>강제 난입</b>: 미스터 시니스터가 공격하려 할 때, 그는 대신 암약합니다."},{"id":"40147","name":"유전자 통달","en":"Genetic Mastery","type":"treachery","enc":true,"set":"Mister Sinister","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 미스터 시니스터가 다음 특성을 가지고 있다면:\n• [[공중]] — 간접 피해 2점을 입습니다.\n• [[야만]] — 당신의 아이덴티티를 소진합니다.\n• [[사이오닉]] — 주요 음모에 위협을 2만큼 놓습니다."},{"id":"40148","name":"분자 제어","en":"Molecular Control","type":"treachery","enc":true,"set":"Mister Sinister","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 미스터 시니스터에게 강인함 상태 카드를 줍니다. 그가 [[야만]] 특성을 가지고 있다면, 그가 입은 피해 4점을 치료합니다.\n<hr />\n[star] <b>강화</b>: 미스터 시니스터에게 강인함 상태 카드를 줍니다.","star":true,"boostStar":true},{"id":"40149","name":"사악한 계략","en":"Sinister Schemes","type":"treachery","enc":true,"set":"Mister Sinister","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 미스터 시니스터가 암약합니다. 그가 [[사이오닉]] 특성을 가지고 있다면, 당신은 혼란에 빠집니다.\n<hr />\n[star] <b>강화</b>: 당신은 혼란에 빠집니다.","star":true,"boostStar":true},{"id":"40150","name":"사악한 일격","en":"Sinister Strike","type":"treachery","enc":true,"set":"Mister Sinister","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때(일상)</b>: 이 카드는 쇄도를 얻습니다.\n<b>공개될 때(히어로)</b>: 미스터 시니스터가 당신을 공격합니다. 그가 [[공중]] 특성을 가지고 있다면, 당신은 기절합니다.\n<hr />\n[star] <b>강화</b>: 당신은 기절합니다.","star":true,"boostStar":true},{"id":"40151","name":"비행","en":"Flight","type":"attachment","enc":true,"set":"Flight","unique":false,"plus":{"atk":1},"tr":["SUPERPOWER"],"permanent":1,"setupCard":1,"traits":["슈퍼파워"],"text":"사전 준비. 빌런에게 장착합니다.\n영속.\n장착된 빌런은 [[공중]] 특성을 얻습니다.\n[star] 장착된 빌런의 공격은 압살을 얻습니다.","star":true},{"id":"40152","name":"공중 폭격","en":"Aerial Bombardment","type":"attachment","enc":true,"set":"Flight","unique":false,"boost":2,"tr":["CONDITION"],"traits":["상태"],"text":"빌런에게 장착합니다.\n[star] 장착된 빌런은 [[공중]] 특성이 없는 캐릭터를 공격하는 동안 공격 +1을 받고 반격 키워드를 무시합니다.\n<b>히어로 행동</b>: 당신의 히어로를 소진하고 [mental][mental] 자원을 소모 → 이 카드를 버림.","star":true},{"id":"40153","name":"손이 닿지 않는 곳","en":"Out of Reach","type":"attachment","enc":true,"set":"Flight","unique":false,"boost":2,"tr":["CONDITION"],"traits":["상태"],"text":"빌런에게 장착합니다.\n공격자나 공격이 [[공중]] 특성을 가지고 있거나 그 공격이 원거리를 가지고 있지 않다면, 빌런은 피해를 입을 수 없습니다.\n<b>히어로 행동</b>: 당신의 히어로를 소진하고 [energy][energy] 자원을 소모 → 이 카드를 버림."},{"id":"40154","name":"유리한 고지","en":"High Ground","type":"treachery","enc":true,"set":"Flight","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 아군 캐릭터에게서 강인함 상태 카드를 모두 버립니다. 플레이어들은 그룹으로서 간접 피해 2점을 입습니다 (빌런이 [[야만]] 특성을 가지고 있다면 대신 간접 피해 4점).\n<hr />\n[star] <b>강화</b>: 빌런이 공격 중이라면, 이 공격은 관통을 얻습니다.","star":true,"boostStar":true},{"id":"40155","name":"괴력","en":"Super Strength","type":"attachment","enc":true,"set":"Super Strength","unique":false,"plus":{"atk":1},"tr":["SUPERPOWER"],"permanent":1,"setupCard":1,"traits":["슈퍼파워"],"text":"사전 준비. 빌런에게 장착합니다.\n영속.\n장착된 빌런은 [[야만]] 특성과 의연을 얻습니다. <i>(의연 캐릭터를 기절시키거나 혼란에 빠뜨리려면 같은 종류의 상태 카드가 2장 필요합니다.)</i>"},{"id":"40156","name":"철벽","en":"Impervious","type":"attachment","enc":true,"set":"Super Strength","unique":false,"boost":2,"tr":[],"traits":[],"text":"빌런에게 장착합니다.\n장착된 빌런이 각 공격으로 입는 피해를 1만큼 감소시킵니다.\n<b>히어로 행동</b>: [physical][physical] 자원을 소모 → 빌런에게 강인함 상태 카드를 주고 이 카드를 버림."},{"id":"40157","name":"투척물","en":"Thrown Object","type":"attachment","enc":true,"set":"Super Strength","unique":false,"boost":3,"plus":{"atk":3},"tr":["ITEM"],"traits":["도구"],"text":"빌런에게 장착합니다.\n[star] 장착된 빌런의 공격은 원거리를 얻습니다.\n[star] <b>강제 반응</b>: 빌런이 공격한 후, 이 카드를 버립니다.","star":true},{"id":"40158","name":"\"그건 내가 가져가지\"","en":"\"I'll Take That\"","type":"treachery","enc":true,"set":"Super Strength","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신이 조종하는 업그레이드 중 자원 비용이 가장 낮은 카드를 버립니다 (빌런이 [[사이오닉]] 특성을 가지고 있다면 대신 가장 높은 카드). 이렇게 버려진 업그레이드가 없다면, 이 카드는 쇄도를 얻습니다."},{"id":"40159","name":"텔레파시","en":"Telepathy","type":"attachment","enc":true,"set":"Telepathy","unique":false,"plus":{"sch":1},"tr":["SUPERPOWER"],"permanent":1,"setupCard":1,"traits":["슈퍼파워"],"text":"사전 준비. 빌런에게 장착합니다.\n영속.\n장착된 빌런은 [[사이오닉]] 특성과 반격 1을 얻습니다. <i>(이 캐릭터가 공격받은 후, 공격한 캐릭터에게 피해 1점을 입힙니다.)</i>"},{"id":"40160","name":"조작된 드라마","en":"Manufactured Drama","type":"obligation","enc":true,"set":"Telepathy","unique":false,"boost":2,"tr":[],"traits":[],"text":"당신이 조종하는 지원은 준비할 수 없습니다.\n<b>공개될 때</b>: 당신이 조종하는 각 지원을 소진합니다. 이렇게 소진된 지원이 없다면, 이 카드는 쇄도를 얻습니다.\n<b>일상 행동</b>: 당신의 아이덴티티를 소진하고 당신이 조종하는 지원마다 당신의 덱 맨 위에서 카드 1장을 버림 → 이 카드를 버림."},{"id":"40161","name":"불화의 씨앗","en":"Sowing Discord","type":"obligation","enc":true,"set":"Telepathy","unique":false,"boost":2,"tr":[],"traits":[],"text":"당신이 조종하는 동료는 준비할 수 없습니다.\n<b>공개될 때</b>: 당신이 조종하는 각 동료를 소진합니다. 이렇게 소진된 동료가 없다면, 이 카드는 쇄도를 얻습니다.\n<b>일상 행동</b>: [mental][mental] 자원을 소모 → 이 카드를 버림."},{"id":"40162","name":"한발 앞서","en":"One Step Ahead","type":"treachery","enc":true,"set":"Telepathy","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신의 손에서 무작위로 카드 1장을 버립니다 (빌런이 [[공중]] 특성을 가지고 있다면 대신 무작위로 2장).\n<hr />\n[star] <b>강화</b>: 빌런이 공격 중이라면, 이 공격은 압살을 얻습니다.","star":true,"boostStar":true},{"id":"40163","name":"스트라이프","en":"* Stryfe","type":"villain","enc":true,"set":"Stryfe","unique":true,"hp":15,"hpStar":true,"atk":0,"sch":1,"stage":1,"tr":["MUTANT LIBERATION FRONT","PSIONIC"],"traits":["뮤턴트 해방 전선","사이오닉"],"text":"[star] 스트라이프가 당신을 공격하는 동안, 그는 공격 +X를 받습니다. X는 당신의 손에 있는 카드 중 가장 많은 유형의 카드 수입니다.","star":true},{"id":"40164","name":"스트라이프","en":"* Stryfe","type":"villain","enc":true,"set":"Stryfe","unique":true,"hp":17,"hpStar":true,"atk":1,"sch":1,"stage":2,"tr":["MUTANT LIBERATION FRONT","PSIONIC"],"traits":["뮤턴트 해방 전선","사이오닉"],"text":"[star] 스트라이프가 당신을 공격하는 동안, 그는 공격 +X를 받습니다. X는 당신의 손에 있는 카드 중 가장 많은 유형의 카드 수입니다.\n<b>공개될 때</b>: 각 플레이어는 [[사이오닉]] 장착 카드가 버려질 때까지 조우 덱 맨 위에서 카드를 버리고, 그 카드를 공개합니다.","star":true},{"id":"40165","name":"스트라이프","en":"* Stryfe","type":"villain","enc":true,"set":"Stryfe","unique":true,"hp":20,"hpStar":true,"atk":1,"sch":2,"stage":3,"tr":["MUTANT LIBERATION FRONT","PSIONIC"],"traits":["뮤턴트 해방 전선","사이오닉"],"text":"[star] 스트라이프가 당신을 공격하는 동안, 그는 공격 +X를 받습니다. X는 당신의 손에 있는 카드 중 가장 많은 유형의 카드 수입니다.\n<b>강제 반응</b>: 당신이 스트라이프를 공격한 후, 피해 X점을 입습니다. X는 당신의 손에 있는 카드 중 가장 많은 유형의 카드 수입니다.","star":true},{"id":"40166a","name":"통제 불능의 힘","en":"Uncontrollable Power","type":"main","enc":true,"set":"Stryfe","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 스트라이프 (I), 스트라이프 (II) <i>(전문가 모드에서는 대신 스트라이프 (II), 스트라이프 (III))</i>. 스트라이프, 호프 서머스 및 일반 조우 세트. 모듈식 조우 세트 둘 <i>(극단적 조치, 뮤턴트 봉기)</i>.\n<b>사전 준비</b>: 호프 서머스를 시작 플레이어가 조종하는 상태로 플레이 영역에 내려놓습니다. 스트라이프의 손아귀를 공개합니다."},{"id":"40166b","name":"통제 불능의 힘","en":"Uncontrollable Power","type":"main","enc":true,"set":"Stryfe","unique":false,"start":0,"target":9,"targetStar":true,"esc":0,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"[star] <b>강제 반응</b>: 빌런 페이즈 1단계를 해결한 후, 각 플레이어는 이 카드에 위협을 X만큼 놓습니다. X는 그 플레이어의 손에 있는 카드 중 가장 많은 유형의 카드 수입니다. 각 플레이어는 X 값을 계산하기 전에 자신의 손에서 카드 1장을 버릴 수 있습니다.\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>","star":true},{"id":"40167a","name":"운명에 맡겨지다","en":"Left to Your Fate","type":"main","enc":true,"set":"Stryfe","unique":false,"stage":2,"tr":[],"traits":[],"text":"Stryfe gains stalwart.\nEach identity gets +2 hand size. Increase the resource cost to play each player card by 1.\n<b>If this stage is completed, the players lose the game.</b>"},{"id":"40167b","name":"운명에 맡겨지다","en":"Left to Your Fate","type":"main","enc":true,"set":"Stryfe","unique":false,"start":0,"target":8,"targetStar":true,"esc":1,"escStar":true,"stage":2,"tr":[],"traits":[],"text":"스트라이프는 견고를 얻습니다.\n각 아이덴티티는 손 크기 +2를 받습니다. 각 플레이어 카드를 플레이하는 자원 비용을 1만큼 증가시킵니다.\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"40168a","name":"스트라이프의 손아귀","en":"Stryfe's Grasp","type":"side","enc":true,"set":"Stryfe","unique":false,"start":4,"tr":[],"crisis":1,"permanent":1,"hinder":6,"hinderStar":true,"traits":[],"text":"영속. 교란 6[per_hero].\n호프 서머스는 스트라이프만 공격할 수 있고 이 음모만 저지할 수 있습니다.\n<b>강제 반응</b>: 스트라이프가 격파되거나 이 음모에서 마지막 위협이 제거된 후, 이 카드를 뒤집고 살아 있는 폭탄을 공개합니다. 이 카드에 있던 위협을 모두 살아 있는 폭탄에 놓습니다."},{"id":"40168b","name":"살아 있는 폭탄","en":"Living Bomb","type":"side","enc":true,"set":"Stryfe","unique":false,"start":3,"tr":[],"crisis":1,"victory":1,"traits":[],"text":"승점 1.\n스트라이프는 격파될 수 없습니다.\n<b>공개될 때</b>: 주요 음모를 스테이지 2A로 진행합니다. 이 효과는 무효화할 수 없습니다."},{"id":"40169","name":"정신 전이","en":"Mental Transferal","type":"attachment","enc":true,"set":"Stryfe","unique":false,"boost":2,"tr":["CONDITION","PSIONIC"],"traits":["상태","사이오닉"],"text":"스트라이프의 손아귀가 플레이 영역에 있다면, 호프 서머스에게 장착합니다. 그렇지 않다면, 당신의 아이덴티티에 장착합니다.\n<b>강제 반응</b>: 스트라이프가 피해를 입은 후, 장착된 캐릭터는 같은 양의 피해를 입습니다. 이 카드를 버립니다."},{"id":"40170","name":"정신 개조","en":"Mind Alteration","type":"attachment","enc":true,"set":"Stryfe","unique":false,"boost":2,"tr":["CONDITION","PSIONIC"],"traits":["상태","사이오닉"],"text":"당신의 아이덴티티에 장착합니다.\n<b>강제 반응</b>: 당신이 이벤트나 업그레이드를 플레이한 후, 피해 1점을 입습니다.\n<b>반응</b>: 당신이 회복한 후, [mental] 자원을 소모 → 이 카드를 버림."},{"id":"40171","name":"정신 함정","en":"Mind Trap","type":"attachment","enc":true,"set":"Stryfe","unique":false,"boost":2,"tr":["CONDITION","PSIONIC"],"traits":["상태","사이오닉"],"text":"당신의 아이덴티티에 장착합니다.\n당신의 동료, 업그레이드, 지원은 소진된 상태로 플레이 영역에 들어옵니다.\n<b>일상 행동</b>: 당신이 조종하는 카드 3장을 소진 → 이 카드를 버림."},{"id":"40172","name":"사이오닉 기억상실","en":"Psionic Amnesia","type":"attachment","enc":true,"set":"Stryfe","unique":false,"boost":2,"tr":["CONDITION","PSIONIC"],"traits":["상태","사이오닉"],"text":"당신의 아이덴티티에 장착합니다.\n당신이 플레이하는 각 동료와 지원의 자원 비용을 2만큼 증가시킵니다.\n<b>반응</b>: 당신이 동료나 지원을 플레이한 후, 당신의 아이덴티티를 소진 → 이 카드를 버림."},{"id":"40173","name":"정신적 관성","en":"Psychic Inertia","type":"attachment","enc":true,"set":"Stryfe","unique":false,"boost":1,"plus":{"atk":-1,"thw":-1},"tr":["CONDITION","PSIONIC"],"traits":["상태","사이오닉"],"text":"당신의 아이덴티티에 장착합니다.\n<b>히어로 행동</b>: 이번 페이즈에 당신의 히어로가 공격하고 저지했다면 → 이 카드를 버림."},{"id":"40174","name":"제로","en":"* Zero","type":"minion","enc":true,"set":"Stryfe","unique":true,"hp":4,"atk":1,"sch":1,"boost":1,"tr":["MUTANT LIBERATION FRONT"],"guard":1,"toughness":1,"patrol":1,"traits":["뮤턴트 해방 전선"],"text":"경호. 순찰. 강인.\n<b>격파될 때</b>: 제로를 격파한 플레이어의 손에 같은 유형의 카드가 3장 이상 없다면, 제로를 조우 덱에 섞어 넣습니다."},{"id":"40175","name":"정신 말소","en":"Cerebral Erasure","type":"side","enc":true,"set":"Stryfe","unique":false,"boost":2,"start":2,"startStar":true,"accel":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신이 조종하는 업그레이드나 지원 1장을 소유자의 손으로 되돌립니다.\n<b>격파될 때</b>: 이 음모를 격파한 플레이어는 자신이 조종하는 업그레이드나 지원 1장을 소유자의 손으로 되돌립니다."},{"id":"40176","name":"텔레파시 위장","en":"Telepathic Camouflage","type":"side","enc":true,"set":"Stryfe","unique":false,"boost":3,"start":2,"hazard":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 플레이어는 이 카드에 위협을 X만큼 놓습니다. X는 그 플레이어의 손에 있는 카드 중 가장 많은 유형의 카드 수입니다."},{"id":"40177","name":"사이오닉 폭주","en":"Psionic Surge","type":"treachery","enc":true,"set":"Stryfe","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 조우 덱 맨 위에서 카드 X장을 버립니다. X는 당신의 손에 있는 카드 중 가장 많은 유형의 카드 수입니다. 이렇게 버려진 각 [[사이오닉]] 카드를 당신에게 뒷면 조우 카드로 나누어 줍니다."},{"id":"40178","name":"정신 장악","en":"Psychic Override","type":"treachery","enc":true,"set":"Stryfe","unique":false,"boost":1,"tr":["PSIONIC"],"traits":["사이오닉"],"text":"<b>공개될 때</b>: 카드 유형 하나를 선택한 후, 당신의 손에서 그 유형이 아닌 카드를 모두 버립니다. 당신의 손 크기까지 카드를 뽑습니다. 당신의 손에 있는 선택한 유형의 카드마다 주요 음모에 위협을 1만큼 놓습니다.\n<hr />\n[star] <b>강화</b>: 당신의 손에서 카드 1장을 버립니다. 그러고 나서, 카드 1장을 뽑습니다.","star":true,"boostStar":true},{"id":"40179","name":"염동력 파동","en":"Telekinetic Wave","type":"treachery","enc":true,"set":"Stryfe","unique":false,"boost":1,"tr":["PSIONIC"],"traits":["사이오닉"],"text":"<b>공개될 때</b>: 당신이 조종하는 업그레이드나 지원 1장을 당신의 손으로 되돌립니다. 스트라이프가 당신을 상대로 활성화합니다.\n<hr />\n[star] <b>강화</b>: 당신의 손에 같은 유형의 카드가 3장 이상 있다면, 주요 음모에 위협을 3만큼 놓습니다.","star":true,"boostStar":true},{"id":"40180","name":"스트로브","en":"* Strobe","type":"minion","enc":true,"set":"Extreme Measures","unique":true,"hp":4,"atk":2,"sch":2,"boost":2,"tr":["MUTANT LIBERATION FRONT"],"patrol":1,"traits":["뮤턴트 해방 전선"],"text":"순찰.\n<b>공개될 때</b>: 다음 중 하나를 선택합니다.\n• 당신이 조종하는 각 캐릭터를 기절시킵니다.\n• 당신이 조종하는 각 캐릭터에게 피해 1점을 입힙니다."},{"id":"40181","name":"템포","en":"* Tempo","type":"minion","enc":true,"set":"Extreme Measures","unique":true,"hp":5,"atk":1,"sch":1,"tr":["MUTANT LIBERATION FRONT"],"traits":["뮤턴트 해방 전선"],"text":"템포가 당신과 교전 중인 동안, 당신은 손 크기 +1을 받습니다.\n[star] <b>강제 반응</b>: 템포가 당신을 상대로 활성화한 후, 당신의 손에 있는 카드 수의 두 배만큼 당신의 덱 맨 위에서 카드를 버립니다.","star":true},{"id":"40182","name":"썸벨리나","en":"* Thumbelina","type":"minion","enc":true,"set":"Extreme Measures","unique":true,"hp":3,"atk":1,"sch":1,"boost":1,"tr":["MUTANT LIBERATION FRONT"],"traits":["뮤턴트 해방 전선"],"text":"공격자가 [[미세]] 특성을 가지고 있지 않다면, 썸벨리나가 각 공격으로 입는 피해량을 1만큼 감소시킵니다.\n<b>공개될 때</b>: 당신이 조종하는 업그레이드 중 자원 비용이 가장 높은 카드를 소유자의 손으로 되돌립니다."},{"id":"40183","name":"와일드사이드","en":"* Wildside","type":"minion","enc":true,"set":"Extreme Measures","unique":true,"hp":5,"atk":3,"sch":0,"boost":3,"tr":["MUTANT LIBERATION FRONT"],"traits":["뮤턴트 해방 전선"],"text":"<b>공개될 때</b>: 다음 중 하나를 선택합니다.\n• 와일드사이드가 당신을 공격합니다.\n• 당신이 조종하는 지원 중 자원 비용이 가장 높은 카드를 소유자의 손으로 되돌립니다."},{"id":"40184","name":"극단적 조치","en":"Extreme Measures","type":"side","enc":true,"set":"Extreme Measures","unique":false,"boost":1,"start":3,"tr":[],"hinder":2,"hinderStar":true,"traits":[],"text":"교란 2[per_hero].\n<b>강제 반응</b>: 플레이어 카드가 플레이 영역에 들어온 후, 그 카드를 조종하는 플레이어는 그 카드에 인쇄된 자원 비용만큼 간접 피해를 입습니다."},{"id":"40185","name":"드래고네스","en":"* Dragoness","type":"minion","enc":true,"set":"Mutant Insurrection","unique":true,"hp":3,"atk":1,"sch":1,"boost":2,"tr":["MUTANT LIBERATION FRONT"],"traits":["뮤턴트 해방 전선"],"text":"[star] <b>강제 난입</b>: 드래고네스가 당신을 상대로 활성화할 때, 그녀는 그 활성화에서 음모 +X와 공격 +X를 받습니다. X는 당신의 손에 있는 [energy] 자원의 수입니다.","star":true},{"id":"40186","name":"포어암","en":"* Forearm","type":"minion","enc":true,"set":"Mutant Insurrection","unique":true,"hp":6,"atk":4,"sch":0,"boost":4,"tr":["MUTANT LIBERATION FRONT"],"traits":["뮤턴트 해방 전선"],"text":"[star] <b>강제 반응</b>: 포어암이 당신을 공격한 후, 당신의 덱 맨 위에서 카드 X장을 버립니다. X는 당신의 손에 있는 [physical] 자원의 수입니다.","star":true},{"id":"40187","name":"리퍼","en":"* Reaper","type":"minion","enc":true,"set":"Mutant Insurrection","unique":true,"hp":4,"atk":2,"sch":1,"boost":2,"tr":["MUTANT LIBERATION FRONT"],"traits":["뮤턴트 해방 전선"],"text":"[star] <b>강제 난입</b>: 리퍼가 당신을 공격할 때, 당신의 손에 최소한 다음 자원이 있다면:\n• [mental][mental] 자원: 당신의 아이덴티티를 기절시킵니다.\n• [mental][mental][mental][mental] 자원: 당신의 아이덴티티를 소진합니다.","star":true},{"id":"40188","name":"사무라이","en":"* Samurai","type":"minion","enc":true,"set":"Mutant Insurrection","unique":true,"hp":5,"atk":2,"sch":1,"boost":2,"tr":["MUTANT LIBERATION FRONT"],"traits":["뮤턴트 해방 전선"],"text":"[star] <b>강제 반응</b>: 사무라이가 당신을 공격한 후, 이 카드에 충전 카운터를 1만큼 놓습니다. 다음 중 하나를 선택합니다.\n• 사무라이에 놓인 충전 카운터의 수만큼 피해를 입습니다.\n• 당신이 조종하는 카드 중 인쇄된 자원 비용이 사무라이에 놓인 충전 카운터의 수 이상인 카드 1장을 버립니다.","star":true},{"id":"40189","name":"뮤턴트 봉기","en":"Mutant Insurrection","type":"side","enc":true,"set":"Mutant Insurrection","unique":false,"boost":2,"start":3,"tr":[],"traits":[],"text":"맹공. <i>(이 음모에 대한 기본 저지는 저지 대신 공격을 사용합니다.)</i>\n각 하수인은 강인을 얻습니다.\n<b>공개될 때</b>: 플레이 영역에 있는 [[뮤턴트 해방 전선]] 캐릭터마다 이 카드에 위협을 2만큼 추가로 놓습니다. 이렇게 추가 위협이 놓이지 않았다면, 이 카드는 쇄도를 얻습니다."},{"id":"40190a","name":"팀 소집","en":"* Assemble the Team","type":"pside","enc":false,"unique":true,"start":4,"startStar":true,"cls":"Campaign","tr":[],"traits":[],"text":"이 음모는 플레이어 부가 음모 제한 수에 포함되지 않습니다.\n<b>격파될 때</b>: 이 카드를 뒤집어 팀 결성 완료를 플레이 영역에 내려놓습니다.\n<i>(팀 결성 완료의 능력으로 각 플레이어는 자신의 덱에서 동료 하나를 무료로 플레이할 수 있습니다.)</i>"},{"id":"40190b","name":"팀 결성 완료","en":"Team Assembled","type":"environment","enc":true,"set":"Next Evolution Campaign","unique":false,"tr":[],"traits":[],"text":"결성 카운터 1개가 놓인 채로 플레이 영역에 들어옵니다.\n<b>행동</b>: 이 카드에서 결성 카운터를 1만큼 제거 → 각 플레이어는 자신의 덱과 버린 더미에서 인쇄된 자원 비용이 3 이하인 동료 하나를 찾아 플레이 영역에 내려놓을 수 있음. <i>(어느 플레이어든 이 능력을 사용할 수 있습니다.)</i>"},{"id":"40191a","name":"은신처 마련","en":"* Establish Safehouse","type":"pside","enc":false,"unique":true,"start":4,"startStar":true,"cls":"Campaign","tr":[],"traits":[],"text":"이 음모는 플레이어 부가 음모 제한 수에 포함되지 않습니다.\n<b>격파될 때</b>: 이 카드를 뒤집고 은신처 확보를 플레이 영역에 내려놓습니다.\n<i>(은신처 확보의 능력으로 플레이어들은 은신처 지원 카드를 얻습니다.)</i>"},{"id":"40191b","name":"은신처 확보","en":"Safehouse Established","type":"environment","enc":true,"set":"Next Evolution Campaign","unique":false,"tr":[],"traits":[],"text":"은신처 카운터를 1만큼 놓은 채로 플레이 영역에 들어옵니다.\n<b>행동</b>: 이 카드에서 은신처 카운터를 1만큼 제거 → 시작 플레이어가 은신처 지원을 자신의 조종하에 플레이 영역에 내려놓음. <i>(은신처는 캠페인 카드입니다.)</i>"},{"id":"40192a","name":"장비 착용","en":"* Gear Up","type":"pside","enc":false,"unique":true,"start":4,"startStar":true,"cls":"Campaign","tr":[],"traits":[],"text":"이 음모는 플레이어 부가 음모 제한 수에 포함되지 않습니다.\n<b>격파될 때</b>: 이 카드를 뒤집고 장비 완료를 플레이 영역에 내려놓습니다.\n<i>(장비 완료의 능력으로 각 플레이어는 파우치 자원 카드를 얻습니다.)</i>"},{"id":"40192b","name":"장비 완료","en":"Geared Up","type":"environment","enc":true,"set":"Next Evolution Campaign","unique":false,"tr":[],"traits":[],"text":"파우치 카운터를 1만큼 놓은 채로 플레이 영역에 들어옵니다.\n<b>행동</b>: 이 카드에서 파우치 카운터를 1만큼 제거 → 각 플레이어는 파우치 자원 카드 1장을 자신의 덱에 섞어 넣음. <i>(파우치는 캠페인 카드입니다.)</i>"},{"id":"40193a","name":"임무 준비","en":"* Mission Prep","type":"pside","enc":false,"unique":true,"start":4,"startStar":true,"cls":"Campaign","tr":[],"traits":[],"text":"이 음모는 플레이어 부가 음모 제한 수에 포함되지 않습니다.\n<b>격파될 때</b>: 이 카드를 뒤집고 임무 준비 완료를 플레이 영역에 내려놓습니다.\n<i>(임무 준비 완료의 능력으로 각 플레이어는 자신의 덱에서 업그레이드 하나를 무료로 플레이할 수 있습니다.)</i>"},{"id":"40193b","name":"임무 준비 완료","en":"Mission Prepped","type":"environment","enc":true,"set":"Next Evolution Campaign","unique":false,"tr":[],"traits":[],"text":"준비 카운터를 1만큼 놓은 채로 플레이 영역에 들어옵니다.\n<b>행동</b>: 이 카드에서 준비 카운터를 1만큼 제거 → 각 플레이어는 자신의 덱과 버린 더미에서 인쇄된 비용이 2 이하인 업그레이드 1장을 찾아 플레이 영역에 내려놓음. <i>(어느 플레이어든 이 능력을 사용할 수 있습니다.)</i>"},{"id":"40194a","name":"기동 훈련","en":"* Practice Maneuvers","type":"pside","enc":false,"unique":true,"start":4,"startStar":true,"cls":"Campaign","tr":[],"traits":[],"text":"이 음모는 플레이어 부가 음모 제한 수에 포함되지 않습니다.\n<b>격파될 때</b>: 이 카드를 뒤집고 숙련된 기동을 플레이 영역에 내려놓습니다.\n<i>(숙련된 기동의 능력으로 플레이어들은 비용이 높은 이벤트 카드를 영구적으로 할인받습니다.)</i>"},{"id":"40194b","name":"숙련된 기동","en":"Practiced Maneuvers","type":"environment","enc":true,"set":"Next Evolution Campaign","unique":false,"tr":[],"traits":[],"text":"인쇄된 비용이 3 이상인 각 이벤트를 플레이하는 비용이 1만큼 줄어듭니다."},{"id":"40195a","name":"방어 준비","en":"* Prepare Defenses","type":"pside","enc":false,"unique":true,"start":4,"startStar":true,"cls":"Campaign","tr":[],"traits":[],"text":"이 음모는 플레이어 부가 음모 제한 수에 포함되지 않습니다.\n<b>격파될 때</b>: 이 카드를 뒤집고 대비된 방어를 플레이 영역에 내려놓습니다.\n<i>(대비된 방어의 능력으로 각 플레이어는 영구적으로 방어 +1과 반격 1을 얻습니다.)</i>"},{"id":"40195b","name":"대비된 방어","en":"Prepared Defenses","type":"environment","enc":true,"set":"Next Evolution Campaign","unique":false,"tr":[],"traits":[],"text":"각 히어로는 방어 +1을 받고 반격 1을 얻습니다."},{"id":"40196","name":"파우치","en":"Pouches","type":"resource","enc":false,"unique":false,"res":"GG","cls":"Basic;Campaign","tr":[],"traits":[]},{"id":"40197","name":"은신처","en":"Safehouse","type":"support","enc":false,"unique":false,"cost":4,"res":"G","cls":"Basic;Campaign","tr":["LOCATION"],"traits":["장소"],"text":"<b>일상 행동</b>: 다음 중 하나를 선택합니다.\n• 당신의 아이덴티티가 입은 피해 2점을 치료합니다.\n• 카드 1장을 뽑음.\n어느 플레이어든 이 능력을 격발할 수 있습니다. (플레이어마다 라운드마다 1회 제한.)"},{"id":"40198","name":"레이디 마스터마인드","en":"* Lady Mastermind","type":"minion","enc":true,"set":"Next Evolution Campaign","unique":true,"hp":3,"atk":1,"sch":1,"boost":2,"surge":1,"tr":["MARAUDER"],"traits":["머로더"],"text":"쇄도.\n<b>공개될 때</b>: 피해 X점을 입습니다. X는 당신의 손에 있는 이벤트 중 비용이 가장 높은 이벤트의 인쇄된 비용입니다.\n<hr />\n[star] <b>강화</b>: 당신의 손에서 이벤트 1장을 버립니다.","star":true,"boostStar":true},{"id":"40199","name":"맬리스","en":"* Malice","type":"minion","enc":true,"set":"Next Evolution Campaign","unique":true,"hp":1,"atk":1,"sch":1,"boost":3,"surge":1,"tr":["MARAUDER"],"traits":["머로더"],"text":"쇄도.\n<b>격파될 때</b>: [[사이오닉]]이 아닌 동료 중 비용이 가장 높은 동료에게 맬리스를 장착합니다. 장착된 동료는 자신의 조종자와 교전합니다. 장착된 동료를 문구 상자가 비어 있는 <i>([[특성]] 제외)</i> [[빙의]] 하수인으로 취급합니다. 장착된 하수인의 음모는 그 하수인의 저지와 같으며, 그 하수인은 부수적 피해를 입지 않습니다."},{"id":"40200","name":"스크램블러","en":"* Scrambler","type":"minion","enc":true,"set":"Next Evolution Campaign","unique":true,"hp":3,"atk":1,"sch":1,"boost":3,"surge":1,"tr":["MARAUDER"],"traits":["머로더"],"text":"쇄도.\n<b>공개될 때</b>: 당신이 조종하는 업그레이드 하나를 버립니다."},{"id":"40201","name":"배니셔","en":"* Vanisher","type":"minion","enc":true,"set":"Next Evolution Campaign","unique":true,"hp":3,"atk":1,"sch":1,"boost":2,"surge":1,"tr":["MARAUDER"],"traits":["머로더"],"text":"쇄도.\n<b>공개될 때</b>: 당신이 조종하는 지원 중 비용이 가장 높은 지원을 당신의 손으로 되돌립니다.\n<hr />\n[star] <b>강화</b>: 당신이 조종하는 지원 중 비용이 가장 높은 지원을 당신의 손으로 되돌립니다.","star":true,"boostStar":true},{"id":"40202","name":"압박","en":"Under Pressure","type":"side","enc":true,"set":"Next Evolution Campaign","unique":false,"boost":2,"start":6,"surge":1,"tr":[],"amplify":1,"traits":[],"text":"쇄도.\n<hr />\n[star] <b>강화</b>: 이번 활성화에서 빌런에게 강화 카드 1장을 추가로 줍니다.","star":true,"boostStar":true},{"id":"40203","name":"과중한 부담","en":"Overburdened","type":"treachery","enc":true,"set":"Next Evolution Campaign","unique":false,"boost":1,"surge":1,"tr":[],"traits":[],"text":"쇄도.\n<b>공개될 때</b>: 당신의 손에서 자원 카드 1장을 버리거나 피해 2점을 입는 것 중 하나를 선택합니다.\n<hr />\n[star] <b>강화</b>: 당신의 손에서 자원 카드 1장을 버리거나 피해 2점을 입는 것 중 하나를 선택합니다.","star":true,"boostStar":true},{"id":"40204","name":"호프 서머스","en":"* Hope Summers","type":"ally","enc":false,"unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":4,"res":"B","cls":"Basic","tr":["X-FORCE"],"traits":["엑스포스"],"text":"호프 서머스는 당신의 아이덴티티에 있는 각 [[특성]]을 얻습니다.\n<b>반응</b>: 당신이 당신의 손에서 호프 서머스를 플레이한 후, 당신의 덱에서 [[슈퍼파워]] 카드 1장을 찾아 당신의 손에 더합니다. <i>(덱을 섞습니다.)</i>"}]});
